def _imgargs():
    """Termux notifications show YOUR logo as the notification picture (the one set in Chrome or with  liquid --logo)."""
    try:
        d = APP + "/logo"
        if os.path.exists(d + "/nopic"):
            write_blank()
            return ["--image-path", d + "/blank.png"]
        if os.path.exists(d + "/custom") and os.path.exists(d + "/icon-512.png"):
            return ["--image-path", d + "/icon-512.png"]
        p = d + "/notify.png"
        os.makedirs(d, exist_ok=True)
        open(p, "wb").write(blob("icon-512.png.z"))
        return ["--image-path", p]
    except Exception:
        return []


def refresh_tool_notes():
    """New picture: every tool card still showing in the notification shade is reposted (same id, same buttons) with the new picture, silently."""
    def go():
        global _CH
        try:
            d = APP + "/notes"
            if not os.path.isdir(d) or not shutil.which("termux-notification-list"):
                return
            o = subprocess.run(["termux-notification-list"], capture_output=True, text=True, timeout=12)
            act = set()
            for n in json.loads(o.stdout or "[]"):
                for k in ("id", "tag"):
                    if n.get(k) not in (None, ""):
                        act.add(str(n[k]))
            if _CH is None:
                h = subprocess.run(["termux-notification", "--help"], capture_output=True, text=True, timeout=8)
                _CH = ["--channel", "liquid_island"] if "--channel" in h.stdout + h.stderr else []
            img = _imgargs()
            for fn in os.listdir(d):
                if not fn.endswith(".json"):
                    continue
                fp = os.path.join(d, fn)
                try:
                    if time.time() - os.path.getmtime(fp) > 172800:
                        os.remove(fp)
                        continue
                    if fn[:-5] not in act:
                        continue
                    a = json.load(open(fp))
                except (OSError, ValueError):
                    continue
                out, skip = [], 0
                for x in a:
                    if skip:
                        skip -= 1
                    elif x in ("--image-path", "--vibrate"):
                        skip = 1
                    elif x not in ("--sound", "--alert-once"):
                        out.append(x)
                out += ["--alert-once"] + img
                for extra in (out, [x for i, x in enumerate(out) if x != "--icon" and (i == 0 or out[i - 1] != "--icon")]):
                    r = subprocess.run(["termux-notification"] + _CH + extra, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL, timeout=15)
                    if r.returncode == 0:
                        break
        except Exception as e:
            log("tool notification refresh failed: %r" % (e,))
    threading.Thread(target=go, daemon=True).start()


def note(i, t, m, c="30d158", q=False):
    def go():
        global _CH
        try:
            if _CH is None:
                o = subprocess.run(["termux-notification", "--help"], capture_output=True, text=True, timeout=8)
                _CH = ["--channel", "liquid_island"] if "--channel" in o.stdout + o.stderr else []
            loud = ["--ongoing", "--alert-once", "--priority", "default"] if q else ["--priority", "max", "--led-color", c, "--vibrate", "80"]
            base = ["termux-notification"] + _CH + ["--id", i, "--title", _DOT.get(c, "\U0001F7E2") + " " + t, "--content", m] + loud
            ic = {"ff453a": "error", "ff9f0a": "warning"}.get(c, "opacity")     # status-bar icon (Material name): a drop, or warning / error
            # best first: status-bar icon + your picture; then the picture only; then the plain notification
            for extra in (["--icon", ic] + _imgargs(), _imgargs(), []):
                r = subprocess.run(base + extra, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL, timeout=15)
                if r.returncode == 0:
                    break
        except Exception as e:
            log("notification failed: %r" % (e,))
    threading.Thread(target=go, daemon=True).start()



def _plugged_sysfs():
    """True/False from /sys/class/power_supply (usb / ac / wireless 'online'), None when it cannot be read."""
    seen = False
    try:
        for p in glob.glob("/sys/class/power_supply/*/online"):
            try:
                v = open(p).read().strip()
            except OSError:
                continue
            seen = True
            if v == "1":
                return True
    except Exception:
        pass
    return False if seen else None

def bat_band(pct):
    """Battery bands, the SAME in Termux, the server and Chrome: 80-100 Excellent, 50-79 Good, 20-49 Fine, below 20 Plug in now."""
    if pct is None or pct < 0:
        return "", "", "", ""
    if pct >= 80:
        return "excellent", "Excellent", "green", ""
    if pct >= 50:
        return "good", "Good", "green", ""
    if pct >= 20:
        return "fine", "Fine", "yellow", ""
    return "low", "Plug in now", "red", "Immediately plug in your charger"


def temp_band(t):
    """(colour, word, advice) for the battery temperature in degrees C - same wording in Termux and Chrome."""
    if t is None:
        return "", "", ""
    if t >= 50:
        return "red", "very hot", "stop now, unplug and let it cool"
    if t >= 45:
        return "red", "hot", "unplug and let it cool down"
    if t >= 40:
        return "orange", "warm", "go easy, avoid heavy use"
    if t >= 35:
        return "yellow", "a little warm", "normal while charging or working"
    if t >= 20:
        return "green", "normal", ""
    if t >= 10:
        return "green", "cool", ""
    return "yellow", "cold", "the battery drains faster in the cold"


