def _lc(p, depth=1):
    try:
        names = os.listdir(p)
    except OSError:
        return
    for n in names:
        fp = os.path.join(p, n)
        if not os.path.isdir(fp):
            continue
        if n != n.lower() and depth < 3:
            try:
                os.rename(fp, fp + ".tmp_lc")
                os.rename(fp + ".tmp_lc", os.path.join(p, n.lower()))
                fp = os.path.join(p, n.lower())
            except OSError:
                continue
        if depth < 3:
            _lc(fp, depth + 1)


def _lower_reports():
    """One time: 'Liquid Reports' and its sub-folders -> small letters (works on case-blind storage too)."""
    for d in ("/sdcard/Download", "/storage/emulated/0/Download", HOME + "/storage/downloads", DL):
        try:
            if "Liquid Reports" in os.listdir(d):
                fp = os.path.join(d, "Liquid Reports")
                os.rename(fp, fp + ".tmp_lc")
                os.rename(fp + ".tmp_lc", os.path.join(d, REPORTS))
            if REPORTS in os.listdir(d):
                _lc(os.path.join(d, REPORTS))
        except OSError:
            pass


def _merge_dir(src, dst):
    """Move every file of src into dst (renumbering runN.html so nothing is overwritten), then remove src."""
    os.makedirs(dst, exist_ok=True)
    for fn in sorted(os.listdir(src)):
        a = os.path.join(src, fn)
        b = os.path.join(dst, fn)
        if os.path.exists(b):
            m = re.match(r"^run(\d+)\.html$", fn)
            if m:
                n = max([int(x.group(1)) for x in (re.match(r"^run(\d+)\.html$", f) for f in os.listdir(dst)) if x] + [0]) + 1
                b = os.path.join(dst, "run%d.html" % n)
            else:
                continue
        try:
            os.rename(a, b)
        except OSError:
            pass
    try:
        os.rmdir(src)
    except OSError:
        pass


def _migrate_spaces():
    """One time: 'liquid reports' (with a space) -> 'liquid_reports', and every tool sub-folder 'flac report' -> 'flac_report' etc."""
    for d in ("/sdcard/Download", "/storage/emulated/0/Download", HOME + "/storage/downloads", DL):
        try:                                                # flac_check -> flac_comment_check, flac_set -> flac_comment_set
            for _o, _n in (("flac_check", "flac_comment_check"), ("flac_set", "flac_comment_set")):
                _a, _b = os.path.join(d, REPORTS, _o), os.path.join(d, REPORTS, _n)
                if os.path.isdir(_a) and not os.path.exists(_b):
                    os.rename(_a, _b)
        except OSError:
            pass
        try:
            old, new = os.path.join(d, "liquid reports"), os.path.join(d, REPORTS)
            if os.path.isdir(old):
                if not os.path.exists(new):
                    os.rename(old, new)
                else:
                    for n in os.listdir(old):
                        a, b = os.path.join(old, n), os.path.join(new, n)
                        if os.path.isdir(a):
                            _merge_dir(a, b)
                    try:
                        os.rmdir(old)
                    except OSError:
                        pass
            if os.path.isdir(new):
                for n in os.listdir(new):
                    a = os.path.join(new, n)
                    if os.path.isdir(a) and " " in n:
                        _merge_dir(a, os.path.join(new, n.replace(" ", "_")))
        except OSError:
            pass


def _migrate_old():
    """One time: rename the old 'Everything Liquid Reports' tree to the new nested 'liquid reports' layout."""
    mp = {"FLAC Library Reports": "flac report", "FLAC Comment Checks": "flac check", "FLAC Set Comment": "flac set",
          "ZIP Comment Checks": "zip comment check", "ZIP Password Checks": "zip password check", "ZIP Set Comment": "zip comment set",
          "ZIP Set Password": "zip password set", "Other Reports": "other"}
    for d in ("/sdcard/Download", "/storage/emulated/0/Download", HOME + "/storage/downloads", DL):
        try:
            R0 = os.path.join(d, REPORTS)
            for a, b in {"flac/library report": "flac report", "flac/comment check": "flac check", "flac/set comment": "flac set",
                         "zip/comment check": "zip comment check", "zip/password check": "zip password check",
                         "zip/set comment": "zip comment set", "zip/set password": "zip password set"}.items():
                src, dst = os.path.join(R0, a), os.path.join(R0, b)
                if os.path.isdir(src) and not os.path.exists(dst):
                    os.rename(src, dst)
            for g in ("flac", "zip"):
                try:
                    os.rmdir(os.path.join(R0, g))
                except OSError:
                    pass
        except OSError:
            pass
        try:
            o, n = os.path.join(d, "Everything Liquid Reports"), os.path.join(d, REPORTS)
            if not os.path.isdir(o):
                continue
            os.makedirs(n, exist_ok=True)
            for a, b in mp.items():
                src, dst = os.path.join(o, a), os.path.join(n, b)
                if os.path.isdir(src) and not os.path.exists(dst):
                    os.makedirs(os.path.dirname(dst), exist_ok=True)
                    os.rename(src, dst)
            try:
                os.rmdir(o)
            except OSError:
                pass
        except OSError:
            pass
    _lower_reports()
    _migrate_spaces()


def report_roots():
    _migrate_old()
    """Every 'liquid_reports' folder that exists on the phone (Downloads, ~/storage links, Termux home)."""
    out, seen = [], set()
    for d in ("/sdcard/Download", "/storage/emulated/0/Download", HOME + "/storage/downloads",
              HOME + "/storage/shared/Download", DL, HOME):
        r = os.path.join(d, REPORTS)
        try:
            rp = os.path.realpath(r)
            if os.path.isdir(r) and rp not in seen:
                seen.add(rp)
                out.append(r)
        except OSError:
            pass
    return out


def report_root():
    r = report_roots()
    return r[0] if r else None


def find_report(sub, fn):
    """Safe lookup: only <root>/<known tool folder>/runN.html, nothing else can be reached."""
    if sub not in SUBS or not re.match(r"^run\d+\.html$", fn or ""):
        return None
    for root in report_roots():
        fp = os.path.join(root, sub, fn)
        if os.path.isfile(fp) and os.path.realpath(fp).startswith(os.path.realpath(root) + os.sep):
            return fp
    return None


def list_reports(tool=None, cap=300):
    """Every report earlier runs saved on the phone (Downloads/liquid_reports/<tool>/runN.html), newest first."""
    out, seen = [], set()
    for root in report_roots():
        for sub, t in SUBS.items():
            if tool and t != tool:
                continue
            try:
                for fn in os.listdir(os.path.join(root, sub)):
                    m = re.match(r"^run(\d+)\.html$", fn)
                    fp = os.path.join(root, sub, fn)
                    if m and os.path.realpath(fp) not in seen:
                        seen.add(os.path.realpath(fp))
                        st = os.stat(fp)
                        out.append({"sub": sub, "tool": t, "name": fn, "n": int(m.group(1)), "t": int(st.st_mtime),
                                    "size": st.st_size, "path": fp})
            except OSError:
                pass
    return sorted(out, key=lambda r: -r["t"])[:cap]


def open_on_phone(fp):
    """Hand the saved report to Android (default browser / viewer), same fallbacks the tools use."""
    url = "file://" + P.quote(fp)
    # first choice: the page from this server over http. Android often swallows file:// links to Downloads without any error, http opens in the browser.
    hurl = "http://localhost:%d/rf/%s/%s?t=%s" % (PORT, P.quote(os.path.basename(os.path.dirname(fp))), P.quote(os.path.basename(fp)), TOKEN)
    for cmd in (["termux-open-url", hurl],
                ["am", "start", "--user", "0", "-a", "android.intent.action.VIEW", "-d", hurl],
                ["termux-open", "--content-type", "text/html", fp], ["termux-open", fp],
                ["am", "start", "-a", "android.intent.action.VIEW", "-d", url, "-t", "text/html"]):
        if not shutil.which(cmd[0]):
            continue
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
            o = (r.stdout or "") + (r.stderr or "")
            if r.returncode == 0 and "Error" not in o:
                return True
        except Exception:
            continue
    return False


HISTF = APP + "/history.jsonl"
_HL = threading.Lock()


def hist_add(ss, code):
    """Every finished run is remembered on disk (survives restarts): when, how long, exit code, which report."""
    rec = {"id": ss.id, "label": ss.label, "tool": ss.tool, "t0": int(ss.t0), "dur": int(time.time() - ss.t0),
           "code": code, "report": None}
    if ss.report:
        _d = os.path.dirname(ss.report)
        sub, nm = os.path.basename(os.path.dirname(_d)) + "/" + os.path.basename(_d), os.path.basename(ss.report)
        if sub in SUBS and re.match(r"^run\d+\.html$", nm):
            rec["report"] = [sub, nm]
    try:
        with _HL:
            os.makedirs(APP, exist_ok=True)
            with open(HISTF, "a", encoding="utf-8") as f:
                f.write(json.dumps(rec) + "\n")
            if os.path.getsize(HISTF) > 150000:
                keep = open(HISTF, encoding="utf-8").read().splitlines()[-300:]
                open(HISTF, "w", encoding="utf-8").write("\n".join(keep) + "\n")
    except OSError:
        pass


def hist_list(n=40):
    out = []
    try:
        with _HL:
            lines = open(HISTF, encoding="utf-8").read().splitlines()[-n:]
        for ln in lines:
            try:
                r = json.loads(ln)
            except ValueError:
                continue
            r["exists"] = bool(r.get("report") and find_report(*r["report"]))
            out.append(r)
    except OSError:
        pass
    return out[::-1]


def hist_clear(tool=None):
    """Forget past runs: all of them, or only one tool's. Returns how many were removed."""
    n = 0
    try:
        with _HL:
            lines = open(HISTF, encoding="utf-8").read().splitlines()
            if not tool:
                n = len(lines)
                os.remove(HISTF)
            else:
                keep = []
                for ln in lines:
                    try:
                        r = json.loads(ln)
                    except ValueError:
                        r = {}
                    if r.get("tool") == tool:
                        n += 1
                    else:
                        keep.append(ln)
                if n:
                    open(HISTF, "w", encoding="utf-8").write("\n".join(keep) + ("\n" if keep else ""))
    except OSError:
        pass
    if n:
        _SYS[0] = 0
    return n



def _hist_raw(n=300):
    """The last n finished runs from history.jsonl, oldest first (light: no report lookups)."""
    out = []
    try:
        with _HL:
            lines = open(HISTF, encoding="utf-8").read().splitlines()[-n:]
        for ln in lines:
            try:
                out.append(json.loads(ln))
            except ValueError:
                pass
    except OSError:
        pass
    return out


TIMEF = os.path.expanduser("~/.liquid_history.json")      # the tools' speed memory (used only for time estimates)


def clear_reports(tool=None):
    """Delete saved HTML reports: every tool's if tool is None, or only the given tool's. Returns how many were removed."""
    n = 0
    for r in list_reports(tool, 10 ** 9):
        try:
            os.remove(r["path"])
            n += 1
        except OSError:
            pass
    if n:
        _SYS[0] = 0
    return n


def ev_reports_cleared(n, tool=None):
    """THE shared activity line for clearing saved reports, scoped to one tool or every tool."""
    ev("O", "\U0001F5D1 cleared %d saved report(s)%s" % (n, (" for %s" % tool) if tool else " for every tool"))


# ------------------------------------------------------------------ tool learning: one persistent model per tool
# Every tool learns ONLY from its own successful runs.  A run counts as finished when the final completion signal appears: the tick
# followed by the word finished, "\u2714 finished" (the run time may follow it: "\u2714 finished  \u00b7  2m 16s").  That is the very line the
# server prints when a run ends with exit 0 and the Chrome terminal prints at the end of the run.  "ALL GOOD" verdicts, progress bars,
# estimates and tool output never count.  Learned data lives in its OWN file (MODELF), apart from history.jsonl, reports and run
# records, and ONLY model_reset() ("Reset Model's Learning Data") erases it.
import math

MODELF = APP + "/model_learning.json"
MODELLK = APP + "/model_learning.lock"
MODEL_CAP, MODEL_HALF = 400, 30                      # newest samples kept per tool / recency half-life (in samples)
FIN_MARK = "\u2714 finished"
_DURP = r"(?:\d+h\s+\d{1,2}m|\d+m(?:\s+\d{1,2}s)?|\d+s)"
_FIN_RE = re.compile(r"\u2714 finished(?:\s+\u00b7\s+%s|\s+\S+\s+\(%s, exit 0\))?" % (_DURP, _DURP))
_ANSI_ALL = re.compile(r"\x1b\[[0-9;?]*[A-Za-z]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)")
_ML = threading.RLock()

# tool -> (model kind, file extensions counted as items, what the item count means)
_MPROF = {"liquid_flac_report": ("powerlaw", (".flac",)),            # scan + group + sort + report: super-linear in files
          "liquid_check_flac_comments": ("theilsen", (".flac",)),    # header-only reads: light, linear in files
          "liquid_set_flac_comment": ("interactive", (".flac",)),    # human answers + write and re-read every file
          "liquid_check_zip_comments": ("huber", (".zip",)),         # one central-directory read per zip (folder scan)
          "liquid_set_zip_comment": ("throughput", (".zip",)),       # rewrites ONE zip: bytes / throughput
          "liquid_check_zip_passwords": ("quantile", (".zip",)),     # 5 typed tries: mostly human time, no real workload
          "liquid_set_zip_password": ("nnls", (".zip",))}            # re-encrypts ONE zip: per-file key cost + bytes
_MNAME = {"liquid_flac_report": "FLAC report", "liquid_check_flac_comments": "FLAC check comments",
          "liquid_set_flac_comment": "FLAC set comment", "liquid_check_zip_comments": "ZIP check comments",
          "liquid_set_zip_comment": "ZIP set comment", "liquid_check_zip_passwords": "ZIP check password",
          "liquid_set_zip_password": "ZIP set password"}


def finished_signal(t):
    """True only for the real final completion line: the tick followed by 'finished', optionally followed by the run time
    ('✔ finished', '✔ finished  ·  2m 16s', '✔ finished liquid_x.py  (2m 16s, exit 0)'). Anything else is not completion:
    'finished' without the tick, 'ALL GOOD', '✔ finished reading 12 files' (a tool's own step line), '▲ ended ...'."""
    try:
        return bool(_FIN_RE.fullmatch(_ANSI_ALL.sub("", str(t)).replace("\r", "").strip()))
    except Exception:
        return False


def fin_event_text(code, label, secs):
    """THE completion line of a run (Termux feed): '✔ finished <tool>  (2m 16s, exit 0)' or '▲ ended <tool>  (.., exit N)'."""
    return "%s %s  (%s, exit %s)" % ("\u2714 finished" if code == 0 else "\u25b2 ended", label, dur(secs), code)


def _fnum(x, lo=0.0, hi=1e15):
    try:
        x = float(x)
    except (TypeError, ValueError):
        return None
    return x if math.isfinite(x) and lo <= x <= hi else None


def _ml_empty():
    return {"v": 1, "epoch": 0, "reset_ts": 0.0, "tools": {}}


def _ml_clean(o):
    """Make whatever was read from disk safe: bad / missing parts are dropped, never raised."""
    if not isinstance(o, dict):
        return None
    st = _ml_empty()
    st["epoch"] = int(_fnum(o.get("epoch"), 0, 1e9) or 0)
    st["reset_ts"] = _fnum(o.get("reset_ts"), 0, 1e12) or 0.0
    tl = o.get("tools") if isinstance(o.get("tools"), dict) else {}
    for name in ALL:
        e = tl.get(name)
        if not isinstance(e, dict):
            continue
        S = []
        for r in (e.get("samples") if isinstance(e.get("samples"), list) else [])[-MODEL_CAP:]:
            d = _fnum(r.get("dur"), 0.05, 7 * 86400) if isinstance(r, dict) else None
            if d is None:
                continue
            S.append({"id": str(r.get("id", ""))[:40], "t0": _fnum(r.get("t0"), 0, 1e12) or 0.0, "t1": _fnum(r.get("t1"), 0, 1e12) or 0.0,
                      "dur": d, "n": _fnum(r.get("n"), 1, 1e9), "b": _fnum(r.get("b"), 1, 1e15)})
        ids = [str(x)[:40] for x in (e.get("ids") if isinstance(e.get("ids"), list) else [])][-600:]
        for r in S:
            if r["id"] and r["id"] not in ids:
                ids.append(r["id"])
        errs = [v for v in (_fnum(x, 0, 50) for x in (e.get("errs") if isinstance(e.get("errs"), list) else [])) if v is not None][-200:]
        st["tools"][name] = {"samples": S, "ids": ids[-600:], "errs": errs, "total": int(_fnum(e.get("total"), 0, 1e9) or len(S))}
    return st


def _ml_read():
    """-> (state, recovered). Never raises: missing = empty, corrupt = move aside and use the backup, else empty."""
    recovered = False
    for f in (MODELF, MODELF + ".bak"):
        try:
            with open(f, encoding="utf-8") as fh:
                st = _ml_clean(json.load(fh))
            if st is not None:
                return st, recovered
            raise ValueError("not a model file")
        except FileNotFoundError:
            continue
        except (OSError, ValueError):
            if f == MODELF:
                try:
                    os.replace(MODELF, MODELF + ".corrupt")
                except OSError:
                    pass
                recovered = True
    return _ml_empty(), False


def _ml_write(st):
    os.makedirs(APP, exist_ok=True)
    tmp = MODELF + ".tmp%d" % os.getpid()
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write(json.dumps(st, separators=(",", ":")))
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, MODELF)
    try:                                                     # a copy of what was just saved: if the main file is ever damaged, nothing is lost
        shutil.copyfile(MODELF, MODELF + ".bak.tmp")
        os.replace(MODELF + ".bak.tmp", MODELF + ".bak")
    except OSError:
        pass


def _ml_txn(fn):
    """Read-modify-write under a thread lock AND a file lock (the server, a Termux command and a CLI run may all touch the file).
    fn(state) -> (changed, result)."""
    with _ML:
        lk = None
        try:
            os.makedirs(APP, exist_ok=True)
            lk = open(MODELLK, "a+")
            fcntl.flock(lk, fcntl.LOCK_EX)
        except OSError:
            lk = None
        try:
            st, rec = _ml_read()
            ch, res = fn(st)
            if ch or rec:
                try:
                    _ml_write(st)
                except OSError as e:
                    log("model data could not be saved: %r" % (e,))
            return res
        finally:
            if lk:
                try:
                    fcntl.flock(lk, fcntl.LOCK_UN)
                    lk.close()
                except OSError:
                    pass


# ---- the seven models (pure Python, no libraries) -----------------------------------------------------------------------------
def _rw(n):
    return [0.5 ** ((n - 1 - i) / float(MODEL_HALF)) for i in range(n)]


def _wq(v, w, q):
    p = sorted(zip(v, w))
    tot, acc = (sum(x[1] for x in p) or 1.0), 0.0
    for x, wi in p:
        acc += wi
        if acc >= q * tot - 1e-12:
            return x
    return p[-1][0]


def _med(v):
    s = sorted(v)
    m = len(s) // 2
    return s[m] if len(s) % 2 else (s[m - 1] + s[m]) / 2.0


def _sg(res, w, floor=0.08):
    """Robust spread of log-residuals (weighted MAD x 1.4826), widened a little when there are few samples."""
    if not res:
        return 0.5
    m = _wq(res, w, .5)
    s = 1.4826 * _wq([abs(r - m) for r in res], w, .5)
    return max(floor, min(1.5, s)) * math.sqrt(1.0 + 2.0 / len(res))


def _solve(A, B):
    k = len(B)
    M = [A[i][:] + [B[i]] for i in range(k)]
    for c in range(k):
        p = max(range(c, k), key=lambda r: abs(M[r][c]))
        if abs(M[p][c]) < 1e-12:
            return None
        M[c], M[p] = M[p], M[c]
        for r in range(k):
            if r != c:
                f = M[r][c] / M[c][c]
                for j in range(c, k + 1):
                    M[r][j] -= f * M[c][j]
    return [M[i][k] / M[i][i] for i in range(k)]


def _wls(rows, y, w):
    k = len(rows[0])
    A, B = [[0.0] * k for _ in range(k)], [0.0] * k
    for r, yi, wi in zip(rows, y, w):
        for i in range(k):
            B[i] += wi * r[i] * yi
            for j in range(k):
                A[i][j] += wi * r[i] * r[j]
    for i in range(k):
        A[i][i] += 1e-9 * (1.0 + A[i][i])
    return _solve(A, B)


def _theil(P):
    P = P[-60:]
    sl = [(P[j][1] - P[i][1]) / (P[j][0] - P[i][0]) for i in range(len(P)) for j in range(i + 1, len(P)) if abs(P[j][0] - P[i][0]) > 1e-9]
    if not sl:
        return None
    m = max(0.0, _med(sl))
    return m, max(0.0, _med([y - m * x for x, y in P]))


def _xy(S, ws, key):
    return [(s[key], s["dur"], w) for s, w in zip(S, ws) if s.get(key)]


def _spread_ok(P, k=0):
    return len(P) >= 3 and len({round(p[k], 6) for p in P}) >= 2


def _fit_typical(S, ws, f=None):
    d = [s["dur"] for s in S]
    m = _wq(d, ws, .5)
    return m, _sg([math.log(x / m) for x in d], ws, .10)


def _fit_quantile(S, ws, f=None):
    """No real workload (a few typed tries): winsorised blend of weighted median and weighted mean, spread from the quantiles."""
    d = [s["dur"] for s in S]
    lo, hi = _wq(d, ws, .05), _wq(d, ws, .95)
    cl = [min(hi, max(lo, x)) for x in d]
    est = 0.5 * _wq(d, ws, .5) + 0.5 * (sum(w * x for w, x in zip(ws, cl)) / sum(ws))
    return est, _sg([math.log(x / est) for x in d], ws, .10)


def _fit_powerlaw(S, ws, f):
    x0, P = f.get("n"), _xy(S, ws, "n")
    if not x0 or not _spread_ok(P):
        return None
    lx, ly, w = [math.log(p[0]) for p in P], [math.log(p[1]) for p in P], [p[2] for p in P]
    sw = sum(w)
    mx, my = sum(a * b for a, b in zip(w, lx)) / sw, sum(a * b for a, b in zip(w, ly)) / sw
    sxx = sum(a * (x - mx) ** 2 for a, x in zip(w, lx))
    if sxx < 1e-9:
        return None
    pw = min(1.6, max(0.6, sum(a * (x - mx) * (y - my) for a, x, y in zip(w, lx, ly)) / sxx))
    a0 = sum(a * (y - pw * x) for a, x, y in zip(w, lx, ly)) / sw
    return math.exp(a0 + pw * math.log(x0)), _sg([y - a0 - pw * x for x, y in zip(lx, ly)], w)


def _fit_theilsen(S, ws, f):
    x0, P = f.get("n"), _xy(S, ws, "n")
    if not x0 or not _spread_ok(P):
        return None
    fit = _theil([(x, y) for x, y, _ in P])
    if not fit:
        return None
    m, b = fit
    return max(b + m * x0, 0.5), _sg([math.log(max(y, .1) / max(b + m * x, .1)) for x, y, _ in P], [p[2] for p in P])


def _fit_interactive(S, ws, f):
    """Human answers + per-file work: slope per file from Theil-Sen, the human part is a log-normal fitted on what is left over."""
    x0, P = f.get("n"), _xy(S, ws, "n")
    if not x0 or not _spread_ok(P):
        return None
    fit = _theil([(x, y) for x, y, _ in P])
    if not fit:
        return None
    m = fit[0]
    w = [p[2] for p in P]
    lh = [math.log(max(y - m * x, 0.5)) for x, y, _ in P]
    mu = _wq(lh, w, .5)
    return m * x0 + math.exp(mu), _sg([v - mu for v in lh], w, .15)


def _fit_huber(S, ws, f):
    x0, P = f.get("n"), _xy(S, ws, "n")
    if not x0 or not _spread_ok(P):
        return None
    rows, y, w0 = [[1.0, p[0]] for p in P], [p[1] for p in P], [p[2] for p in P]
    c, w = _wls(rows, y, w0), w0
    if not c:
        return None
    for _ in range(12):
        res = [yi - c[0] - c[1] * r[1] for r, yi in zip(rows, y)]
        k = 1.345 * max(1.4826 * _wq([abs(e) for e in res], w0, .5), 0.05 * sum(y) / len(y), 1e-6)
        w = [a * (1.0 if abs(e) <= k else k / abs(e)) for a, e in zip(w0, res)]
        c2 = _wls(rows, y, w)
        if not c2:
            break
        c = c2
    a0, b0 = max(0.0, c[0]), max(0.0, c[1])
    return max(a0 + b0 * x0, 0.5), _sg([math.log(yi / max(a0 + b0 * r[1], .1)) for r, yi in zip(rows, y)], w0)


def _fit_throughput(S, ws, f):
    """Fixed cost + bytes / throughput. The fixed cost comes from a weighted line through (MB, seconds), the throughput is a recency-weighted
    rate (MB per second), so it follows a phone that throttles or speeds up."""
    b0, P = f.get("b"), _xy(S, ws, "b")
    if not b0 or len(P) < 2:
        return None
    mb, y, w = [p[0] / 1048576.0 for p in P], [p[1] for p in P], [p[2] for p in P]
    o = min(_wq(y, w, .10), 0.5 * _wq(y, w, .5))
    if max(mb) - min(mb) > 1e-6 and len(P) >= 3:
        c = _wls([[1.0, m] for m in mb], y, w)
        if c:
            o = min(max(0.0, c[0]), 0.9 * min(y))
    den = sum(a * max(yi - o, 0.05 * yi) for a, yi in zip(w, y))
    thr = sum(a * m for a, m in zip(w, mb)) / den if den > 0 else 0
    if thr <= 0:
        return None
    return o + (b0 / 1048576.0) / thr, _sg([math.log(yi / max(o + m / thr, .1)) for m, yi in zip(mb, y)], w)


def _fit_nnls(S, ws, f):
    """t = fixed + a * entries + c * MB with every coefficient >= 0 (exact: tries every subset of the terms, keeps the best fit)."""
    names = [k for k in ("n", "b") if f.get(k)]
    if not names:
        return None
    P = [(s, w) for s, w in zip(S, ws) if all(s.get(k) for k in names)]
    if len(P) < 3:
        return None
    rows = [[1.0] + [(s[k] if k == "n" else s[k] / 1048576.0) for k in names] for s, _ in P]
    y, w0 = [s["dur"] for s, _ in P], [w for _, w in P]
    x0 = [1.0] + [(f[k] if k == "n" else f[k] / 1048576.0) for k in names]
    best, w = None, w0
    for rnd in (0, 1):
        best = None
        for mask in range(1, 1 << len(x0)):
            sub = [i for i in range(len(x0)) if mask >> i & 1]
            if len(sub) > len(P) - 1:
                continue
            c = _wls([[r[i] for i in sub] for r in rows], y, w)
            if not c or any(v < -1e-9 for v in c):
                continue
            sse = sum(a * (yi - sum(cv * r[i] for cv, i in zip(c, sub))) ** 2 for a, r, yi in zip(w, rows, y))
            sc = sse * (1.0 + 0.05 * len(sub))
            if best is None or sc < best[0]:
                best = (sc, sub, c)
        if not best:
            return None
        if rnd == 0:                                              # second pass: down-weight points far from the first fit
            res = [yi - sum(cv * r[i] for cv, i in zip(best[2], best[1])) for r, yi in zip(rows, y)]
            s = max(1.4826 * _wq([abs(e) for e in res], w0, .5), 0.05 * sum(y) / len(y), 1e-6)
            w = [a * (1.0 if abs(e) <= 3 * s else 3 * s / abs(e)) for a, e in zip(w0, res)]
    sub, c = best[1], best[2]
    est = sum(cv * x0[i] for cv, i in zip(c, sub))
    return max(est, 0.5), _sg([math.log(yi / max(sum(cv * r[i] for cv, i in zip(c, sub)), .1)) for r, yi in zip(rows, y)], w0)


_FITS = {"powerlaw": _fit_powerlaw, "theilsen": _fit_theilsen, "interactive": _fit_interactive, "huber": _fit_huber,
         "throughput": _fit_throughput, "nnls": _fit_nnls, "quantile": _fit_quantile}


def _clean(S):
    """Leave out runs that were far SLOWER than the rest for the same amount of work (a run left open while the person walked away, a stalled
    phone). They stay in the file; they just do not steer the prediction. Needs 3+ runs; never drops more than half."""
    if len(S) < 3:
        return S
    lr = [math.log(s["dur"] / (s["n"] if s.get("n") else 1.0)) for s in S]
    m = _med(lr)
    mad = 1.4826 * _med([abs(x - m) for x in lr])
    lim = m + max(math.log(3.0), 3.5 * mad)
    keep = [s for s, x in zip(S, lr) if x <= lim]
    return keep if len(keep) * 2 >= len(S) else S


def _predict_from(tool, S, feats):
    """Predicted run time from a tool's own samples -> {est, lo, hi (80% range), n, kind, basis} or None when it has learned nothing."""
    S = sorted([s for s in S if s.get("dur", 0) > 0], key=lambda s: s.get("t1", 0))
    if not S:
        return None
    S = _clean(S)
    kind, ws, f = _MPROF.get(tool, ("quantile",))[0], _rw(len(S)), feats or {}
    try:
        r = _FITS[kind](S, ws, f)
    except Exception:
        r = None
    basis = "workload" if r and kind != "quantile" else "typical"
    if r is None or not math.isfinite(r[0]) or r[0] <= 0:
        r = _fit_typical(S, ws)
    est, sg = r
    return {"est": est, "lo": est * math.exp(-1.2816 * sg), "hi": est * math.exp(1.2816 * sg), "n": len(S), "kind": kind, "basis": basis}


# ---- workload of a run (what the model's size feature is) ---------------------------------------------------------------------
def workload_probe(tool, path, budget=3.0):
    """{'n': items, 'b': bytes} for a path a tool is about to work on, or {} when it cannot be told (never raises, 3 s at most)."""
    try:
        exts, p, tend = _MPROF.get(tool, ("quantile", ()))[1], os.path.expanduser(str(path).strip().strip("\"'")), time.time() + budget
        if not exts:
            return {}
        n = b = 0
        if os.path.isfile(p):
            b = os.path.getsize(p)
            if tool == "liquid_check_zip_comments" or exts != (".zip",):
                n = 1 if p.lower().endswith(exts) else 0
            else:
                import zipfile
                with zipfile.ZipFile(p) as z:
                    n = len(z.namelist())
        elif os.path.isdir(p) and tool in ("liquid_flac_report", "liquid_check_flac_comments", "liquid_set_flac_comment", "liquid_check_zip_comments"):
            for root, _d, fs in os.walk(p):
                for fn in fs:
                    if fn.lower().endswith(exts):
                        n += 1
                        try:
                            b += os.path.getsize(os.path.join(root, fn))
                        except OSError:
                            pass
                if time.time() > tend:
                    return {}                                     # too big to count in time: unknown, not a wrong number
        else:
            return {}
        return {k: v for k, v in (("n", n), ("b", b)) if v}
    except Exception:
        return {}


# ---- the one place a finished run becomes a training sample -------------------------------------------------------------------
def learn_finish(tool, rid, t0, t1, secs, code, sig, feats=None, intr=False):
    """Record a SUCCESSFUL run for its own tool's model. Needs: the real '✔ finished' signal, exit code 0, no Ctrl-C / stop, a known tool,
    a run that began after the last learning reset, and an id not seen before (no duplicates). Returns a result dict or None."""
    try:
        if tool not in ALL or code != 0 or intr or not finished_signal(sig):
            return None
        secs = float(secs)
        if not (0.05 <= secs <= 7 * 86400):
            return None
        feats = feats or {}
        smp = {"id": str(rid)[:40], "t0": round(float(t0), 3), "t1": round(float(t1), 3), "dur": round(secs, 3),
               "n": _fnum(feats.get("n"), 1, 1e9), "b": _fnum(feats.get("b"), 1, 1e15)}
        if not smp["id"]:
            return None

        def fn(st):
            if smp["t0"] < st["reset_ts"]:
                return False, None                                # started before "Reset Model's Learning Data": not part of the new learning
            e = st["tools"].setdefault(tool, {"samples": [], "ids": [], "errs": [], "total": 0})
            if smp["id"] in e["ids"]:
                return False, None
            pr = _predict_from(tool, e["samples"], smp)           # BEFORE learning it: an honest out-of-sample prediction
            err = min(abs(pr["est"] - secs) / secs, 50.0) if pr else None
            e["samples"] = (e["samples"] + [smp])[-MODEL_CAP:]
            e["ids"] = (e["ids"] + [smp["id"]])[-600:]
            if err is not None:
                e["errs"] = (e["errs"] + [round(err, 4)])[-200:]
            e["total"] += 1
            return True, {"n": len(e["samples"]), "total": e["total"], "pred": pr, "err": err, "dur": secs,
                          "next": _predict_from(tool, e["samples"], smp)}
        return _ml_txn(fn)
    except Exception as e:
        log("learning sample not saved: %r" % (e,))
        return None


def learn_sess(ss, code, sig):
    """Called by the session at the moment it prints the completion line."""
    try:
        if getattr(ss, "_learned", False) or ss.tool not in ALL:
            return
        ss._learned = True
        f = dict(ss.wl)
        if "n" not in f and ss.pt_total:
            f["n"] = ss.pt_total
        m0 = _mastery_of(ss.tool)
        r = learn_finish(ss.tool, ss.id, ss.t0, ss.t_end, (ss.dur_m - ss.wait) if ss.dur_m and ss.dur_m - ss.wait >= 0.5 else ss.dur_m, code, sig, f, intr=ss.intr)
        _learn_say(ss.tool, ss.label, r)
        if r:                                                  # Termux feed + Chrome feed: how far this run moved the model
            m1 = _mastery_of(ss.tool)
            ev(TOOLC.get(ss.tool, "Y"), "\U0001F9EA %s mastery %d%% \u2192 %d%%  %s  \u00b7 %d run%s learned" % (ss.label, round(m0), round(m1), _mbar(m1), r["total"], "" if r["total"] == 1 else "s"))
    except Exception:
        pass


def _learn_say(tool, label, r):
    if not r:
        return
    pr = r.get("pred")
    ev(TOOLC.get(tool, "Y"), "\U0001F9E0 %s learned run #%d (%s)%s \u00b7 %s model" % (
        label, r["total"], dur(r["dur"]),
        (" \u00b7 predicted ~%s, off by %d%%" % (dur(pr["est"]), round(100 * r["err"]))) if pr and r["err"] is not None else " \u00b7 first sample for this tool",
        _MPROF.get(tool, ("quantile",))[0]))


def learn_announce(ss, refined=False):
    """Termux + Chrome feed line: what the tool's own model expects this run to take (again when the size of the work is known)."""
    try:
        if ss.tool not in ALL:
            return
        st, _ = _ml_read()
        pr = _predict_from(ss.tool, (st["tools"].get(ss.tool) or {}).get("samples", []), ss.wl)
        ss.pred = pr["est"] if pr else None
        if not refined:                                        # tell Termux + Chrome that this tool's model is now learning the live run
            _m = _mastery_of(ss.tool)
            ev(TOOLC.get(ss.tool, "Y"), "\U0001F9EA %s model learning this run \u00b7 mastery %d%% %s" % (ss.label, round(_m), _mbar(_m)))
        if not pr:
            if not refined:
                ev(TOOLC.get(ss.tool, "Y"), "\U0001F52E %s: nothing learned yet, this run teaches its model" % ss.label)
            return
        if refined and pr["basis"] != "workload":
            return
        ev(TOOLC.get(ss.tool, "Y"), "\U0001F52E %s predicted ~%s (%s to %s) \u00b7 %s model, %s \u00b7 learned from %d run%s" % (
            ss.label, dur(pr["est"]), dur(pr["lo"]), dur(pr["hi"]), pr["kind"],
            "sized for this work" if pr["basis"] == "workload" else "typical time", pr["n"], "" if pr["n"] == 1 else "s"))
    except Exception:
        pass


def _mastery(total, n, err, lo, hi):
    """Same formula the Chrome page uses: average of experience, accuracy and confidence (0..100). 0 while nothing is learned."""
    if not n:
        return 0.0
    ex = (1 - math.exp(-(total or 0) / 40.0)) * 100
    ac = (100 - min(100.0, err * 100)) if err is not None else 0.0
    cf = (100.0 * lo / hi) if (lo is not None and hi) else 0.0
    return (ex + ac + cf) / 3.0


def _mbar(p, w=10):
    k = max(0, min(w, int(round(w * p / 100.0))))
    return "\u25b0" * k + "\u25b1" * (w - k)


def _mastery_of(tool):
    try:
        for t in model_summary()["tools"]:
            if t["tool"] == tool:
                return t["mastery"]
    except Exception:
        pass
    return 0.0


def model_summary():
    """Everything the Server tab and Termux show about the models."""
    st, _ = _ml_read()
    out = []
    for name in ALL:
        e = st["tools"].get(name) or {}
        S, errs = e.get("samples", []), e.get("errs", [])
        pr = _predict_from(name, S, S[-1]) if S else None
        R = [x["n"] / x["dur"] for x in S if x.get("n") and x["dur"] > 0]
        try:
            byt = len(json.dumps(e, separators=(",", ":")))
        except Exception:
            byt = 0
        _ex = (_MPROF.get(name, ("", ()))[1] or (".x",))[0]
        out.append({"tool": name, "cap": MODEL_CAP, "bytes": byt, "unit": "zips" if _ex == ".zip" else "files",
                    "rate": (sum(R[-5:]) / len(R[-5:])) if R else None, "best": max(R) if R else None,
                    "last_ts": S[-1].get("t1") if S else None, "secs": round(sum(x["dur"] for x in S), 1), "items": int(sum(x.get("n") or 0 for x in S)), "name": _MNAME.get(name, name), "kind": _MPROF.get(name, ("quantile",))[0], "n": len(S),
                    "total": e.get("total", 0), "est": pr["est"] if pr else None, "lo": pr["lo"] if pr else None,
                    "hi": pr["hi"] if pr else None, "last": S[-1]["dur"] if S else None,
                    "err": (sum(errs[-10:]) / len(errs[-10:])) if errs else None,
                    "err0": (sum(errs[:10]) / len(errs[:10])) if len(errs) >= 12 else None})
        _t = out[-1]
        _t["color"] = CLR.get(TOOLC.get(name, "Y"), CLR["Y"])                       # the tool's own colour (same as its lines in the Termux feed)
        _t["mastery"] = round(_mastery(_t["total"], _t["n"], _t["err"], _t["lo"], _t["hi"]), 1)
        _c = CUR                                                                     # live: this tool is running right now (Chrome and Termux read the same state)
        _t["live"] = ({"id": _c.id, "el": round(max(0.0, time.time() - _c.t0 - _c.wait), 1), "pred": _c.pred, "pct": getattr(_c, "pcl", None)}
                      if _c is not None and _c.code is None and _c.tool == name else None)
    return {"epoch": st["epoch"], "reset_ts": st["reset_ts"], "file": MODELF, "tools": out}


def model_reset(src="Termux"):
    """Reset Model's Learning Data: the ONLY operation that erases learned model data. Every tool's model goes back to its initial state
    (no samples) and starts learning again from scratch. Reset Server, Clear Runs, deleting reports / records never call this."""
    def fn(st):
        ep = st["epoch"] + 1
        st.clear()
        st.update(_ml_empty())
        st["epoch"], st["reset_ts"] = ep, time.time()
        return True, True
    try:
        _ml_txn(fn)
        for f in (MODELF + ".bak", MODELF + ".corrupt", TIMEF):   # TIMEF = the tools' own speed memory, the other half of what they learned
            try:
                os.remove(f)
            except OSError:
                pass
        ev("R", "\U0001F9E0 Reset Model's Learning Data (%s): all %d tool models were erased and start learning again from scratch" % (src, len(ALL)))
        return True
    except Exception as e:
        log("model reset failed: %r" % (e,))
        return False


def model_cmd(a=None):
    """liquid --model: what every tool's model has learned (key m in the live panel)."""
    j = model_summary()
    say("LEARNING MODELS  (own file: %s)" % j["file"].replace(HOME, "~"), "G")
    for t in j["tools"]:
        line(("  %-20s" % t["name"], TOOLC.get(t["tool"], "W")), ("%-11s" % t["kind"], "D"),
             (("%3d run%s \u00b7 ~%s" % (t["n"], " " if t["n"] == 1 else "s", dur(t["est"]))) if t["n"] else "  no data yet", "W"),
             (("  \u00b1%d%% recent error" % round(100 * t["err"])) if t["err"] is not None else "", "D"),
             ("  %s %3d%%" % (_mbar(t["mastery"], 10), round(t["mastery"])), TOOLC.get(t["tool"], "W")),
             (("  \u25b6 learning now %s" % dur(t["live"]["el"])) if t.get("live") else "", "G"))
    return 0


def model_reset_cmd(a):
    """liquid --reset-model [--yes]: Reset Model's Learning Data."""
    if "--yes" not in a and "-y" not in a:
        if not sys.stdin.isatty():
            say("Add --yes to confirm:  liquid --reset-model --yes", "O")
            return 1
        try:
            ans = input("Reset Model's Learning Data? Every tool's model forgets what it learned. (y/N) ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            ans = ""
        if ans not in ("y", "yes"):
            say("Cancelled. Nothing was erased.", "O")
            return 0
    say("Model learning data erased. Every model starts again from scratch." if model_reset("Termux") else "Could not reset the learning data.", "G")
    return 0


RESET_DELAY = 5            # seconds between the "full reset" line + notification and the real reset (so you see both first)
_RESET = [0]


def ev_reset():
    """THE shared activity line for the full server reset. One sentence for every way of asking for it (Chrome's Full reset button,
    Termux key z pressed twice, liquid --reset-all), so it is ONE shared item (kind R): it reaches the Termux feed and the Chrome
    feed through activity.log, and the Android notification rides with it (note() is never counted)."""
    ev("R", "\u21ba server FULL RESET requested: settings, logo, past runs, log and notifications will be erased (learned model data is kept)")


def wipe_everything():
    """(Learned model data - model_learning.json and the tools' speed memory TIMEF - is NOT erased here: only model_reset() does that.)
    Erase everything Liquid remembers: settings (config.json), the logo / picture (back to No picture), past runs and the speed
    memory, the activity log and server log, the Termux-only totals file, and every Liquid notification. Saved HTML reports are erased too;
    the access token is kept. Runs in the reset helper, after the server has been stopped."""
    clear_reports()
    for f in (CFGF, HISTF, APP + "/activity.log", APP + "/activity.log.1", APP + "/termux_net.json", APP + "/termux_net.json.tmp"):
        try:
            os.remove(f)
        except OSError:
            pass
    try:
        open(APP + "/server.log", "w").close()
    except OSError:
        pass
    try:
        shutil.rmtree(APP + "/logo", ignore_errors=True)
        os.makedirs(APP + "/logo", exist_ok=True)
        open(APP + "/logo/nopic", "w").write("1")        # the same state as "picture removed": black + NO LOGO
    except OSError:
        pass
    if shutil.which("termux-notification-remove"):
        for i in range(9100, 9109):
            try:
                subprocess.run(["termux-notification-remove", str(i)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=5)
            except Exception:
                pass
    _SYS[0] = 0


def reset_run():
    """The reset itself (runs in its own helper process, so it can stop the server): stop the server and any running tool,
    erase everything, start a fresh server, then post the 'done' notification."""
    st = get_status()
    if st:
        stop_server(quiet=True)
        if get_status():
            kill_server()
    hist_clear(None)
    wipe_everything()
    if st:
        start_server()
    note("9108", "\u21ba Full reset done", "settings, logo, past runs, log and notifications erased (saved reports too)", "30d158")
    time.sleep(1)


def reset_start():
    """Chrome button, Termux key z (twice) and liquid --reset-all all come here: write the ONE shared line, post the notification now,
    and only RESET_DELAY seconds later start the helper that really resets. Returns False if a reset is already on its way."""
    if time.time() - _RESET[0] < RESET_DELAY + 30:
        return False
    _RESET[0] = time.time()
    ev_reset()
    note("9108", "\u21ba Full reset in %d s" % RESET_DELAY, "settings, logo, past runs, log and notifications will be erased (saved reports too; learned model data is kept)", "ff453a")
    threading.Timer(RESET_DELAY, lambda: subprocess.Popen([sys.executable, SELF, "--reset-run"], stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, start_new_session=True)).start()
    return True


def reset_cmd(a):
    """liquid --reset-all [--yes]   erase settings, logo, past runs, log, notifications and saved reports (learned model data is kept)"""
    if "--yes" not in a and "-y" not in a:
        if not sys.stdin.isatty():
            say("Add --yes to confirm:  liquid --reset-all --yes", "O")
            return 1
        try:
            ans = input("Erase ALL settings, the logo, past runs, the log and notifications? Saved reports are deleted too. (y/N) ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            ans = ""
        if ans not in ("y", "yes"):
            say("Cancelled. Nothing was erased.", "O")
            return 0
    if reset_start():
        say("Full reset in %d s (watch the feed and the notification). The server restarts by itself." % RESET_DELAY, "R")
        time.sleep(RESET_DELAY + 1)
    else:
        say("A full reset is already on its way.", "O")
    return 0


def usage_stats(tool=None):
    """Use statistics from the run history (all tools, or one tool): runs, ok %, average / longest time, total run time,
    busiest tool, and the longest time before the newest run (to spot a new record). None when there are no runs yet."""
    h = [r for r in _hist_raw() if not tool or r.get("tool") == tool]
    if not h:
        return None
    ds = [int(r.get("dur") or 0) for r in h]
    ok, cnt = sum(1 for r in h if r.get("code") == 0), {}
    for r in h:
        cnt[r.get("tool")] = cnt.get(r.get("tool"), 0) + 1
    top = max(cnt, key=cnt.get)
    return {"n": len(h), "ok": ok, "pct": 100 * ok // len(h), "avg": sum(ds) // len(h), "max": max(ds), "sum": sum(ds),
            "last": ds[-1], "prev": max(ds[:-1]) if len(ds) > 1 else 0, "top": top, "topn": cnt[top]}


def _usage_line():
    """Termux-only USAGE row (dashboard / status): total runs, ok %, busiest tool, total run time."""
    try:
        u = usage_stats()
        if u:
            line(("USAGE     ", "D"), ("%d runs \u00b7 %d%% ok \u00b7 busiest %s (%d) \u00b7 %s run time" % (
                u["n"], u["pct"], u["top"], u["topn"], dur(u["sum"])), "M"))
        else:
            line(("USAGE     ", "D"), ("no runs yet", "M"))
    except Exception:
        pass


_SYS = [0, {}]
_SYS_BAT = [0, None]
_SYS_NET = [0, 0, 0, 0, 0, 0]
_SYS_APP = [0, 0]


# ---- CPU % : ONE sampler shared by every screen (Termux, Chrome tiles, Server tab, activity feed) --------------------
# Old code took "change since the last call" inside sysinfo(), so each screen measured a different window (0.01 s to 5 s)
# and, on Android, summed only Termux's own processes (always 1-2 %). Now a background thread samples once a second,
# lightly smooths it, and everyone reads the same number.
_CPU = {"lk": threading.Lock(), "v": None, "src": "", "t": 0.0, "ps": None, "pk": None, "th": None}


def _cpu_stat_read():
    """(idle, total) jiffies from /proc/stat, or None when Android blocks / empties it."""
    v = [int(x) for x in open("/proc/stat").readline().split()[1:]]
    if len(v) < 4:
        return None
    tot = sum(v[:8])                      # guest columns are already inside user / nice
    return (v[3] + (v[4] if len(v) > 4 else 0), tot) if tot > 0 else None


def _cpu_own_ticks():
    """CPU time (utime+stime+waited children) of every process we are allowed to read (on Android: only our own)."""
    tk = 0
    for n in os.listdir("/proc"):
        if n.isdigit():
            try:
                f = open("/proc/%s/stat" % n).read().rsplit(")", 1)[1].split()
                tk += int(f[11]) + int(f[12]) + int(f[13]) + int(f[14])
            except (OSError, IndexError, ValueError):
                pass
    return tk


def _cpu_freq_pct():
    """Average clock position of the cores between their lowest and highest speed (0-100), or None if unreadable.
    Android governors raise the clock within milliseconds of real load, so this follows the true load of the whole phone."""
    tot, n = 0.0, 0
    for p in glob.glob("/sys/devices/system/cpu/cpu[0-9]*/cpufreq"):
        try:
            cur = int(open(p + "/scaling_cur_freq").read())
            hi = lo = None
            for fn in ("cpuinfo_max_freq", "scaling_max_freq"):
                try:
                    hi = int(open(p + "/" + fn).read())
                    break
                except (OSError, ValueError):
                    pass
            for fn in ("cpuinfo_min_freq", "scaling_min_freq"):
                try:
                    lo = int(open(p + "/" + fn).read())
                    break
                except (OSError, ValueError):
                    pass
            if hi and hi > (lo or 0):
                tot += max(0.0, min(1.0, (cur - (lo or 0)) / float(hi - (lo or 0))))
                n += 1
        except (OSError, ValueError):
            pass
    return 100.0 * tot / n if n else None


def _cpu_sample():
    """One reading: (percent since the previous reading, source) or (None, source) while there is no baseline yet."""
    c, now = _CPU, time.time()
    try:
        s = _cpu_stat_read()
    except Exception:
        s = None
    if s:                                               # real system-wide number
        o, c["ps"] = c["ps"], s
        if o and s[1] - o[1] >= 1:
            return max(0.0, min(100.0, 100.0 * (1.0 - (s[0] - o[0]) / float(s[1] - o[1])))), "stat"
        return None, "stat"
    own = None                                          # Android: /proc/stat is blocked -> estimate
    try:
        tk, cores = _cpu_own_ticks(), max(1, os.cpu_count() or 1)
        o, c["pk"] = c["pk"], (now, tk)
        if o and now > o[0] and tk >= o[1]:
            own = min(100.0, 100.0 * (tk - o[1]) / float(os.sysconf("SC_CLK_TCK")) / (now - o[0]) / cores)
    except Exception:
        pass
    fr = None
    try:
        fr = _cpu_freq_pct()
    except Exception:
        pass
    if fr is not None:
        return max(fr, own or 0.0), "freq"              # never lower than what Termux itself provably used
    return own, "own"


def _cpu_loop():
    first = True
    while True:
        try:
            v, src = _cpu_sample()
            if v is not None:
                with _CPU["lk"]:
                    _CPU["v"] = v if _CPU["v"] is None else 0.6 * v + 0.4 * _CPU["v"]
                    _CPU["src"], _CPU["t"] = src, time.time()
        except Exception:
            pass
        time.sleep(0.3 if first else 1.0)
        first = False


def cpu_now():
    """(percent, source) shared by every screen. source: 'stat' = exact; 'freq' / 'own' = estimate (Android hides /proc/stat)."""
    c = _CPU
    if not (c["th"] and c["th"].is_alive()):
        with c["lk"]:
            if not (c["th"] and c["th"].is_alive()):
                c["th"] = threading.Thread(target=_cpu_loop, daemon=True)
                c["th"].start()
    t_end = time.time() + 2.0
    while c["v"] is None and time.time() < t_end:       # only the very first call waits (about 0.3 s)
        time.sleep(0.05)
    if c["v"] is not None and time.time() - c["t"] > 15:    # sampler stuck for a long time: do not show a stale number
        return None, c["src"]
    return c["v"], c["src"]


CPU_WARN, CPU_HOT = 50, 70          # CPU %: below 50 green  |  50-69 orange  |  70 and up red   (the only place to change it)


def cpu_level(v):
    """'G' green / 'O' orange / 'R' red for a CPU percent (same letters the Termux colours use); 'D' (grey) when unknown."""
    return "D" if v is None else "R" if v >= CPU_HOT else "O" if v >= CPU_WARN else "G"


def cpu_txt(sd):
    """'12' (exact) or '~12' (estimate) for the text lines; '?' when unknown."""
    v = (sd or {}).get("cpu")
    return "?" if v is None else ("~" if sd.get("cpu_est") else "") + str(int(round(v)))


def sysinfo():
    """Phone + server numbers for the Server tab (battery, storage, memory, load, run totals). Cached 15 s."""
    now = time.time()
    if now - _SYS[0] < .5 and _SYS[1]:
        return _SYS[1]
    d = {"python": sys.version.split()[0], "api": bool(shutil.which("termux-notification")), "up": int(now - START),
         "tool_runs": NRUN[0]}
    try:
        d["load"] = [round(x, 2) for x in os.getloadavg()]
    except OSError:
        pass
    try:
        m = {}
        for ln in open("/proc/meminfo"):
            k, _, v = ln.partition(":")
            m[k] = int(v.split()[0]) * 1024
        d["ram_free"], d["ram_total"] = m.get("MemAvailable", 0), m.get("MemTotal", 0)
    except Exception:
        pass
    try:
        u = shutil.disk_usage(DL)
        d["disk_free"], d["disk_total"] = u.free, u.total
    except OSError:
        pass
    d["cores"] = os.cpu_count() or 0
    try:                                                    # cpu %: shared 1 s sampler (same number on every screen)
        _cv, _cs = cpu_now()
        if _cv is not None:
            d["cpu"], d["cpu_src"], d["cpu_est"] = round(_cv, 1), _cs, _cs != "stat"
            d["cpu_level"] = cpu_level(round(_cv))                      # colour is decided on the shown (rounded) number
            d["cpu_color"] = CLR[d["cpu_level"]]                        # hex, ready for Chrome
            d["cpu_warn"], d["cpu_hot"] = CPU_WARN, CPU_HOT             # Chrome reads the limits from here too
    except Exception:
        pass
    try:                                                    # battery: slow call, refreshed every 15 s only
        if now - _SYS_BAT[0] > 15 and shutil.which("termux-battery-status"):
            b = json.loads(subprocess.run(["termux-battery-status"], capture_output=True, text=True, timeout=6).stdout)
            _st, _pl = str(b.get("status", "")).upper(), str(b.get("plugged", "")).upper()
            _sf = _plugged_sysfs()
            _cu = b.get("current")
            # Android sometimes reports NOT_CHARGING / UNPLUGGED while a charger is connected (optimized charging,
            # bypass, some Oppo / Realme builds), so check four things: status, plugged, the kernel's usb/ac/wireless
            # "online" files, and (only when those files can't be read) the sign of the battery current.
            # one source for charging, the same one the Chrome tiles and the Termux line show:
            # Android's own status, or a real charger (AC / USB / WIRELESS). The kernel files are only a fallback
            # when Termux gives no status at all. "not UNPLUGGED" was wrong: other values also mean "no charger".
            _termux_known = bool(_st) or bool(_pl)
            _chg = (_st in ("CHARGING", "FULL") or _pl in ("AC", "USB", "WIRELESS")
                    or (not _termux_known and _sf is True))
            _SYS_BAT[1] = {"pct": int(b.get("percentage", -1)), "status": str(b.get("status", "")).title(),
                           "temp": b.get("temperature"), "plugged": str(b.get("plugged", "")),
                           "health": str(b.get("health", "")).title(), "ma": _cu, "charging": _chg,
                           "label": "Charging" if _chg else ("Discharging" if _st == "DISCHARGING" else "On battery"),
                           "raw": {"status": _st, "plugged": _pl, "sysfs_online": _sf, "current": _cu}}   # see /api/system
            _lv, _bl, _bc, _ba = bat_band(_SYS_BAT[1]["pct"])
            _tc, _tw, _ta = temp_band(b.get("temperature"))
            _SYS_BAT[1].update({"level": _lv, "band": _bl, "color": _bc, "advice": _ba,
                                "temp_color": _tc, "temp_note": (_tw + (" - " + _ta if _ta else "")) if _tw else ""})
            _SYS_BAT[0] = now
        if _SYS_BAT[1]:
            d["battery"] = _SYS_BAT[1]
    except Exception:
        _SYS_BAT[0] = now
    try:                                                    # shared with the browser: network speed, server memory, app data, task
        r, t = net_bytes()
        o = _SYS_NET
        if o[0] and now > o[0]:
            o[4], o[5] = (r - o[1]) / (now - o[0]) / 1024.0, (t - o[2]) / (now - o[0]) / 1024.0
        o[0], o[1], o[2] = now, r, t
        d["net_dn"], d["net_up"] = round(o[4], 1), round(o[5], 1)
    except Exception:
        pass
    try:
        for ln in open("/proc/self/status"):
            if ln.startswith("VmRSS"):
                d["srv_mem"] = int(ln.split()[1]) * 1024
    except Exception:
        pass
    try:
        if now - _SYS_APP[0] > 20:
            _SYS_APP[0], _SYS_APP[1] = now, sum(os.path.getsize(os.path.join(a, f)) for a, _d, fs in os.walk(APP) for f in fs)
        d["app_bytes"] = _SYS_APP[1]
    except Exception:
        pass
    try:
        x = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        x.connect(("10.255.255.255", 1))
        d["lan"] = x.getsockname()[0]
        x.close()
        for ln in open("/proc/self/status"):
            if ln.startswith("Threads"):
                d["thr"] = int(ln.split()[1])
    except Exception:
        pass
    d["task"] = CUR.meta() if CUR else None
    d["pid"] = os.getpid()
    try:
        d["swap_free"], d["swap_total"] = m.get("SwapFree", 0), m.get("SwapTotal", 0)
    except Exception:
        pass
    h = hist_list(300)
    d["runs_total"], d["runs_ok"] = len(h), sum(1 for r in h if r.get("code") == 0)
    _ds = [int(r.get("dur") or 0) for r in h]
    d["avg_run"], d["max_run"] = (sum(_ds) // len(_ds), max(_ds)) if _ds else (None, None)   # Chrome-only 'Avg run' tile
    rl = list_reports()
    d["reports"], d["reports_bytes"] = len(rl), sum(r["size"] for r in rl)
    d["report_folders"] = report_roots()
    _SYS[0], _SYS[1] = now, d
    return d


def refresh_copies():
    """The loose copies in Downloads get the current logo too: liquid_commands.html (the OPENING page you start from the Files app)
    and liquid_quickstart.html. Called after every logo change, after a reset and every time the server starts."""
    for n, src, always in (("liquid_commands.html", "liquid_start.html", True), ("liquid_quickstart.html", "liquid_quickstart.html", False)):
        try:
            fp = DL + "/" + n
            if os.path.isdir(DL) and (always or os.path.exists(fp)):
                new = skin(text(src))
                try:
                    if open(fp, encoding="utf-8").read() == new:
                        continue
                except (OSError, UnicodeError):
                    pass
                tmp = fp + ".tmp"
                open(tmp, "w", encoding="utf-8").write(new)
                os.replace(tmp, fp)
        except OSError as e:
            log("could not refresh %s in Downloads: %r" % (n, e))


def _stamp():
    """Version of the picture: changes with every new picture and every reset (so icons, manifest, caches all refresh)."""
    best = 0
    for fn in ("custom", "nopic"):
        try:
            best = max(best, os.stat(APP + "/logo/" + fn).st_mtime_ns // 1000000)
        except OSError:
            pass
    return str(best)


def pic_bg():
    """data: URL of the big, sharp picture you chose (bg.jpg; icon-512.png for older uploads), or ''."""
    try:
        d = APP + "/logo"
        if not os.path.exists(d + "/custom"):
            return ""
        for fn, mt in (("bg.png", "png"), ("bg.jpg", "jpeg"), ("icon-512.png", "png")):
            p = d + "/" + fn
            if os.path.exists(p):
                with open(p, "rb") as f:
                    return "data:image/%s;base64,%s" % (mt, base64.b64encode(f.read()).decode())
    except OSError:
        pass
    return ""


