_OLD_BK = re.compile(r'<style id="lgbk">.*?</script>', re.S)
_OLD_INL = re.compile(r"<script>\(function\(\)\{var r=document\.documentElement,K='lgtheme',b;.*?</script>", re.S)


def glass_toggle(h):
    """Every page (Commands, quick start, tool reports): ONE fixed Picture/Black button in its own top bar + the picture in a glass box at the bottom.
    Older copies of this block (saved reports, Downloads copy) are replaced, never doubled."""
    if "/*lgv6*/" in h:
        return h
    h = _OLD_BK.sub("", h)
    h = _OLD_INL.sub("", h)
    return h.replace("</head>", GLASS_JS + "</head>", 1) if "</head>" in h else GLASS_JS + h


def upgrade_reports():
    """Saved reports from before this change get the fixed button + bottom picture box too (once; already-new ones are skipped)."""
    try:
        for root in report_roots():
            for dp, _, fs in os.walk(root):
                for fn in fs:
                    if fn.endswith(".html"):
                        p = os.path.join(dp, fn)
                        try:
                            t = open(p, encoding="utf-8").read()
                            t2 = glass_toggle(t)
                            if t2 != t:
                                open(p, "w", encoding="utf-8").write(t2)
                        except (OSError, UnicodeError):
                            pass
    except Exception:
        pass


