    """Put the logo you chose (Setup tab / liquid --logo / Send to Termux) into every embedded page: small logo + big sharp background."""
    h = h.replace("</head>", '<style id="lgfix12">html #lgbar{border-bottom:0!important}html.lgblack #lgbar{background:#000!important}html .wrap{padding-bottom:calc(200px + env(safe-area-inset-bottom,0px))!important}html *:has(#termwrap):not(#termwrap):not(html):not(body){border:0!important;outline:0!important;box-shadow:none!important;background:none!important;background-image:none!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important}html #termwrap{background:#000!important;border:0!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.16)!important}.seg>button svg,.seg>button .nm{transform:scale(calc(1 + var(--mag,0)*.55));transform-origin:50% 60%;transition:none}.seg>button svg{scale:calc(1 + var(--sc,0)*.12);transition:scale .25s ease-out}html.lgblack.lgblack.lgblack.lgblack #navseg>button,html.lgblack.lgblack.lgblack.lgblack #nav2seg>button{border:0!important;box-shadow:none!important;background:none!important;outline:0!important}.seg>button svg{width:26px;height:26px}.seg>button .nm{font-size:10.5px}html.lgblack.lgblack.lgblack.lgblack.lgblack.lgblack #navseg>button:not(#lgtb),html.lgblack.lgblack.lgblack.lgblack.lgblack.lgblack #nav2seg>button:not(#lgtb),html #navseg>button,html #nav2seg>button{border:0!important;border-width:0!important;box-shadow:none!important;background:none!important;background-image:none!important;outline:0!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important}html #navseg>button::before,html #navseg>button::after,html #nav2seg>button::before,html #nav2seg>button::after{display:none!important;content:none!important}html:not(.lgblack) :is(.glass,.card,.chip,.tag,.warn,.cmdbox,.runbox,.ft,.guide,section,.tint,.fpanel,.f,.pre,.more,pre,.tile,.gr,.gcov,.dcov,.cv){border:1px solid rgba(255,255,255,.55)!important}html:not(.lgblack) html.lgpic::after{content:"";position:absolute;top:80px;left:50vw;width:160px;height:160px;margin-left:-80px;z-index:60;border:0;outline:0;border-radius:28px;box-shadow:0 14px 30px rgba(0,0,0,.5);cursor:pointer;background:var(--lgbgi) center/172px 172px no-repeat}html.lgpic .orbs::before{inset:0;background:var(--lgbgi) center/cover no-repeat;filter:none!important}html.lgpic body::before{inset:0;background:var(--lgbgi) center/cover no-repeat!important;filter:none!important}html:not(.lgblack) :is(button:not(.ok),a.btn):not(#lgtb){border:1px solid rgba(255,255,255,.6)!important;border-radius:999px}</style></head>', 1)
