def banner():
    t = "\u25d6\u25d7 LIQUID  commands \u00b7 Termux is the engine"
    try:
        w = max(len(t) + 4, shutil.get_terminal_size((45, 24)).columns)      # the box fills the whole width
    except Exception:
        w = len(t) + 4
    pad = " " * (w - len(t) - 4)
    say("\u256d" + "\u2500" * (w - 2) + "\u256e", "G")
    line(("\u2502 ", "G"), ("\u25d6\u25d7 LIQUID", "G"), ("  commands \u00b7 Termux is the engine" + pad, "D"), (" \u2502", "G"))
    say("\u2570" + "\u2500" * (w - 2) + "\u256f", "G")


def _gb(n):
    return "%.1f GB" % (n / 1e9)


def recent(n=10):
    """The last n server events (what happened while you were away)."""
    pos, rows = act_read(-1, short=True)
    for k, tm, tx in rows[-n:]:
        say(pfit("  %s  " % tm, tx), k if k in CLR else "W")
    if not rows:
        say("  (no events yet)", "D")


def dash(st=None, events=8):
    """Everything the server knows: server, page, task, phone, work done, last runs, last events. (key d, or  liquid --dash)"""
    st = st or get_status()
    if st:
        line(("SERVER    ", "D"), ("\u25cf running", "G"), ("   pid %d   up %s   build %s" % (st["pid"], dur(st["up"]), st["build"]), "W"))
        line(("PAGE      ", "D"), (URL, "B"), ("   Chrome connected: ", "D"), ("yes" if st["scanner"] else "waiting", "G" if st["scanner"] else "O"))
        cur = st.get("cur")
        run = bool(cur and cur["running"])
        line(("TASK      ", "D"), ((("\u25b6 " + cur["label"] + "  " + dur(time.time() - cur["t0"])) if run else "idle"), TOOLC.get(cur.get("tool"), "Y") if run else "D"))
    else:
        line(("SERVER    ", "D"), ("\u25cb not running", "R"), ("   press  s  to start it", "O"))
    try:
        d = sysinfo()
    except Exception:
        d = {}
    b = d.get("battery")
    if b:
        line(("PHONE     ", "D"), ("battery %d%% %s" % (b["pct"], (b.get("band") or "").lower() + (" \u00b7 charging" if b.get("charging") else "") + ((" \u00b7 " + b["advice"].lower()) if b.get("advice") else "")), "R" if (b.get("color") == "red" and not b.get("charging")) else "Y" if b.get("color") == "yellow" else "G"),
             ("   %s C%s" % (b["temp"], (" \u00b7 " + b["temp_note"]) if b.get("temp_note") else "") if b.get("temp") is not None else "", "R" if b.get("temp_color") == "red" else "O" if b.get("temp_color") == "orange" else "W"))
    if d.get("ram_total"):
        line(("MEMORY    ", "D"), ("%s free of %s" % (_gb(d["ram_free"]), _gb(d["ram_total"])), "W"),
             ("   cpu %s%%" % cpu_txt(d) if d.get("cpu") is not None else "", d.get("cpu_level") or "W"),
             ("   load %s" % " ".join(str(x) for x in d.get("load", [])) if d.get("load") else "", "D"))
    if d.get("disk_total"):
        line(("STORAGE   ", "D"), ("%s free of %s" % (_gb(d["disk_free"]), _gb(d["disk_total"])), "R" if d["disk_free"] < 1e9 else "W"))
    line(("WORK      ", "D"), ("%d runs (%d ok)   %d reports saved" % (d.get("runs_total", 0), d.get("runs_ok", 0), d.get("reports", 0)), "W"))
    try:
        _ms = model_summary()
        line(("LEARNING  ", "D"), ("%d runs learned across %d tool models" % (sum(t["n"] for t in _ms["tools"]), sum(1 for t in _ms["tools"] if t["n"])), "W"),
             ("   liquid --model", "D"))
        for _t in _ms["tools"]:
            if _t.get("live"):
                line(("          ", "D"), ("\U0001F9EA %s learning now \u00b7 %s%s \u00b7 mastery %d%% %s" % (_t["name"], dur(_t["live"]["el"]), (" of ~" + dur(_t["live"]["pred"])) if _t["live"]["pred"] else "", round(_t["mastery"]), _mbar(_t["mastery"])), TOOLC.get(_t["tool"], "G")))
    except Exception:
        pass
    custom = os.path.exists(APP + "/logo/custom")
    line(("NOTIFY    ", "D"), ("on" if cfg()["notify"] else "off", "G" if cfg()["notify"] else "O"),
         ("   Termux:API %s   picture: %s" % ("ok" if d.get("api") else "MISSING", "your logo" if custom else "built-in"), "D"))
    if events:
        termux_consts()
        say("LAST EVENTS", "D")
        recent(events)


def panel(st=None):
    """Status block shown when you type  liquid : server state, page link, settings and the server keys."""
    st = st or get_status()
    banner()
    if st:
        line(("SERVER    ", "D"), ("\u25cf running", "G"), ("   pid %d   up %s   build %s" % (st["pid"], dur(st["up"]), st["build"]), "W"))
        line(("PAGE      ", "D"), (URL, "B"), ("   Chrome connected: ", "D"),
             ("yes" if st["scanner"] else "waiting", "G" if st["scanner"] else "O"))
        cur = st.get("cur")
        line(("TASK      ", "D"), (("\u25b6 " + cur["label"] + "  " + dur(time.time() - cur["t0"])) if cur and cur["running"] else "idle", TOOLC.get(cur.get("tool"), "Y") if cur and cur["running"] else "D"))
    else:
        line(("SERVER    ", "D"), ("\u25cb not running", "R"), ("   press  s  to start it", "O"))
    if st:
        dash(st, 0)
