def log_tail(n=14):
    for f, t in ((APP + "/server.log", "server.log"), (APP + "/activity.log", "activity feed")):
        say("--- %s (last %d lines)" % (t, n), "G")
        try:
            rows = open(f, encoding="utf-8", errors="replace").read().splitlines()
            if f.endswith("activity.log"):                      # tile / heartbeat lines are Chrome-card only
                rows = [x for x in rows if LIVE_MARK not in x.split("|", 3)[-1][:1] or x.count("|") < 3]
            for ln in rows[-n:]:
                k, _, r = ln.partition("|") if f.endswith("activity.log") else ("D", "", "|" + ln)
                tm, _, tx = r.partition("|")
                tx, _, sh = tx.partition("|") if f.endswith("activity.log") else (tx, "", "")
                tx = sh or tx
                if k[:1] == "L" and len(k) == 2:
                    tx, k = "\u2506 " + tx, k[1:]
                say(pfit("%s  " % tm, tx) if tm else pfit("", tx), k if k in CLR else "D")
        except OSError:
            say("  (empty)", "D")


def config_cmd(a):
    """liquid --config                    show
       liquid --config speed 0.5 pace 0.1 slow 3 lh 1.9 notify off"""
    if a:
        kv = {a[i]: a[i + 1] for i in range(0, len(a) - 1, 2)}
        bad = [k for k in kv if k not in LIM]
        if bad or len(a) % 2:
            say("Settings: " + "  ".join("%s %s..%s" % (k, v[0], v[1]) for k, v in LIM.items()), "O")
            say("Example:  liquid --config speed 0.5 pace 0.1 slow 3 notify off", "D")
            return 1
        old = cfg()
        new = cfg_set(**kv)
        ch = ["%s %s>%s" % (k, old[k], new[k]) for k in LIM if old[k] != new[k]]
        if ch:
            ev("O", "\u2699 setting changed in Termux: " + ", ".join(ch))
    cfg_line()
    say("  speed = page animations (1 = original, lower = calmer)   pace = seconds after each tool output line", "D")
    say("  slow = tool animations x slower   lh = line spacing of the terminal in Chrome (1.2 tight .. 2.4 airy)", "D")
    say("  notify = browser / phone notifications  (the page picks changes up within seconds)", "D")
    return 0


_RPIC = re.compile(r'(?:<link rel="icon" href="[^"]*">)?<style id="lgpic">.*?</style>|<style id="lgvars">.*?</style>|<style id="lgmore">.*?</style>|<img class="lgl" src="[^"]*" alt="">', re.S)


def restyle_reports(new):
    """Reports already made: drop the old picture (reset) or swap in the current one (new picture)."""
    css = logo = ""
    if new:
        u = pic_bg()
        try:
            h = open(APP + "/logo/header.txt").read().strip()
        except OSError:
            h = ""
        h = h if re.fullmatch(r"data:image/(?:png|jpeg);base64,[A-Za-z0-9+/=]+", h) else u
        if u:
            sh = "linear-gradient(rgba(0,0,0,0),rgba(0,0,0,0))"
            css = ('<link rel="icon" href="%s"><style id="lgpic">html{padding-top:44px}.orbs{background:%s,url(%s) center/cover no-repeat!important;filter:none!important}'
                   '.orbs::before,.orbs::after{display:none!important}html::before{content:"";display:block;position:relative;z-index:0;box-sizing:border-box;height:200px;margin:16px 16px 0;border-radius:26px;border:1px solid rgba(255,255,255,.55);outline:0;box-shadow:inset 0 1px 0 rgba(255,255,255,.7),inset 0 -1px 0 rgba(255,255,255,.2),inset 0 0 22px rgba(255,255,255,.12),0 10px 28px rgba(0,0,0,.3);background:linear-gradient(180deg,rgba(255,255,255,.22),rgba(255,255,255,0) 120px),linear-gradient(135deg,rgba(255,255,255,.14),rgba(255,255,255,.03),rgba(255,255,255,.1))}html::after{content:"";position:absolute;top:80px;left:50vw;width:160px;height:160px;margin-left:-80px;z-index:60;border:0;outline:0;border-radius:28px;box-shadow:0 14px 30px rgba(0,0,0,.5);cursor:pointer;background:url(@@U@@) center/172px 172px no-repeat}'
                   '.ct::before,.step::before{content:"";display:inline-block;width:20px;height:20px;margin-right:9px;vertical-align:-4px;border-radius:6px;background:url(%s) center/contain no-repeat}h1::after{content:"";margin-left:auto;flex:0 0 44px;width:44px;height:44px;display:none!important;background:url(%s) center/contain no-repeat}.li::before{content:"";flex:0 0 12px;height:12px;align-self:center;border-radius:4px;background:url(%s) center/contain no-repeat}body::before,body::after{display:none!important}'
                   '.glass,.glass.tint,.card,.chip,.tag,code,.warn,.cmd button,.f,.pre,pre.mono,.fpanel{background:none!important;-webkit-backdrop-filter:none!important;'
                   'backdrop-filter:none!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.26)!important}body{text-shadow:0 1px 3px rgba(0,0,0,.8)}'
                   'header,header.glass{position:relative!important;top:auto!important}h1{display:flex!important;align-items:center;gap:16px}.lgl{flex:0 0 auto;width:40px;height:40px;border-radius:0;object-fit:contain;margin:0;box-shadow:none}</style>').replace('@@U@@', u) % (h, sh, u, h, h, h)
            logo = '<img class="lgl" src="%s" alt="">' % h
            css += '<style id="lgmore">:root{--lgbgi:url(' + u + ');--lglogo:url(' + h + ')}' + PIC_MORE.replace('html.lgpic', 'html').replace('html::before', 'html::before') + '</style>'
    if not new:
        css, logo = '<link rel="icon" href="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20256%20256%22%3E%3Crect%20width%3D%22256%22%20height%3D%22256%22%20fill%3D%22%23000%22%2F%3E%3Ctext%20x%3D%22128%22%20y%3D%22118%22%20fill%3D%22%23fff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2234%22%20text-anchor%3D%22middle%22%3ENo%3C%2Ftext%3E%3Ctext%20x%3D%22128%22%20y%3D%22160%22%20fill%3D%22%23fff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2234%22%20text-anchor%3D%22middle%22%3Epicture%3C%2Ftext%3E%3C%2Fsvg%3E"><style id="lgpic">.orbs,body::before,body::after{background:#000!important;filter:none!important}.orbs::before,.orbs::after{display:none!important}header,header.glass{position:relative!important;top:auto!important}h1{display:flex!important;align-items:center;gap:16px}.lgl{flex:0 0 auto;width:40px;height:40px;border-radius:0;object-fit:contain;margin:0;box-shadow:none}</style>', '<img class="lgl" src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20256%20256%22%3E%3Crect%20width%3D%22256%22%20height%3D%22256%22%20fill%3D%22%23000%22%2F%3E%3Ctext%20x%3D%22128%22%20y%3D%22118%22%20fill%3D%22%23fff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2234%22%20text-anchor%3D%22middle%22%3ENo%3C%2Ftext%3E%3Ctext%20x%3D%22128%22%20y%3D%22160%22%20fill%3D%22%23fff%22%20font-family%3D%22sans-serif%22%20font-size%3D%2234%22%20text-anchor%3D%22middle%22%3Epicture%3C%2Ftext%3E%3C%2Fsvg%3E" alt="No picture">'
    for root in report_roots():
        for dp, _, fs in os.walk(root):
            for fn in fs:
                if not fn.endswith(".html"):
                    continue
                p = os.path.join(dp, fn)
                try:
                    t = open(p, encoding="utf-8").read()
                    seen = [0]

                    def sub(m):
                        if m.group(0).startswith("<img"):
                            return logo
                        if m.group(0).startswith("<style id=\"lgvars\"") or m.group(0).startswith("<style id=\"lgmore\""):
                            return ""
                        seen[0] = 1
                        return css
                    t2 = _RPIC.sub(sub, t)
                    if css and not seen[0] and "</head>" in t2:
                        t2 = t2.replace("</head>", css + "</head>", 1)
                    t2 = glass_toggle(t2)
                    if t2 != t:
                        open(p, "w", encoding="utf-8").write(t2)
                except (OSError, UnicodeError):
                    pass


def reset_logo():
    """Remove your picture everywhere: app icons, header, page background, notification picture, silhouette."""
    d = APP + "/logo"
    os.makedirs(d, exist_ok=True)
    open(d + "/nopic", "w").write("1")                  # notifications + tools: no picture until you add one
    for fn in ("custom", "bg.jpg", "bg.png", "icon-192.png", "icon-512.png", "icon-maskable.png", "header.txt", "silhouette.png", "notify.png"):
        try:
            os.remove(os.path.join(d, fn))
        except OSError:
            pass
    write_blank()
    refresh_copies()
    restyle_reports(False)
    _signal_note_refresh()
    ev("M", "\u25c6 picture removed: black background, No picture shown where pictures were")


def silhouette_cmd(path="", quiet=False):
    """liquid --silhouette [pic.png]   white silhouette of your logo (use as a status-bar icon in another app)."""
    say = (lambda *a, **k: None) if quiet else globals()["say"]
    d = APP + "/logo"
    src = path if path and os.path.isfile(path) else d + "/icon-512.png"
    if not os.path.isfile(src):
        say("No logo yet. Set one first:  liquid --logo pic.png", "O")
        return 1
    try:
        from PIL import Image
    except ImportError:
        say("Needs Pillow:  pkg install python-pillow", "R")
        return 1
    im = Image.open(src).convert("RGBA")
    im.thumbnail((96, 96), Image.LANCZOS)                       # whole picture, no squash, no crop
    _q = Image.new("RGBA", (96, 96), (0, 0, 0, 0))
    _q.paste(im, ((96 - im.width) // 2, (96 - im.height) // 2))
    im = _q
    a = im.getchannel("A")
    if a.getextrema() == (255, 255):              # no transparent background: dark shapes become the silhouette
        a = Image.eval(im.convert("L"), lambda v: 255 - v)
    out = Image.new("RGBA", (96, 96), (255, 255, 255, 0))
    out.putalpha(a)
    os.makedirs(d, exist_ok=True)
    out.save(d + "/silhouette.png")
    say("Silhouette saved: " + d + "/silhouette.png", "G")
    return 0


def auto_silhouette():
    """Every new picture (Chrome upload or liquid --logo) makes a fresh white silhouette; the old one is never left behind."""
    try:
        sp = APP + "/logo/silhouette.png"
        if os.path.exists(sp):
            os.remove(sp)
        silhouette_cmd("", True)
    except Exception:
        pass


def _make_icons(path, keep_bg=False):
    """One picture file -> icon-192 / icon-512 / icon-maskable / header.txt / bg.*  (Pillow if installed, else the raw bytes).
    Returns '' when done, or the reason it failed."""
    import io as _io
    d = APP + "/logo"
    os.makedirs(d, exist_ok=True)
    raw = open(path, "rb").read()
    is_png, is_jpg = raw[:4] == b"\x89PNG", raw[:2] == b"\xff\xd8"
    try:
        from PIL import Image, ImageOps
    except ImportError:
        Image = None
    if Image is not None:
        try:
            im = ImageOps.exif_transpose(Image.open(path)).convert("RGBA")
        except Exception:
            try:
                im = Image.open(path).convert("RGBA")
            except Exception as e:
                return "cannot read that picture (%r)" % (e,)
        if not keep_bg:
            for _o in ("bg.jpg", "bg.png"):                                      # the report picture: your ORIGINAL file, untouched
                if os.path.exists(d + "/" + _o):
                    os.remove(d + "/" + _o)
            if is_jpg:
                _wr(d + "/bg.jpg", raw)
            elif is_png:
                _wr(d + "/bg.png", raw)
            else:
                _b = _io.BytesIO()
                im.save(_b, "PNG")
                _wr(d + "/bg.png", _b.getvalue())
        w, h = im.size
        m = max(w, h)
        _sq = Image.new("RGBA", (m, m), (0, 0, 0, 0))
        _sq.paste(im, ((m - w) // 2, (m - h) // 2))                              # whole picture, no crop, no background
        for name, size in (("icon-192.png", 192), ("icon-512.png", 512), ("icon-maskable.png", 512)):
            _wr(d + "/" + name, _render_icon(_sq, size, name == "icon-maskable.png"))
        _b = _io.BytesIO()
        _sq.resize((256, 256), Image.LANCZOS).save(_b, "PNG")
        _wr(d + "/header.txt", ("data:image/png;base64," + base64.b64encode(_b.getvalue()).decode()).encode())
        return ""
    # no Pillow: use the file as it is (browsers and Android read PNG and JPEG whatever the name says)
    if not (is_png or is_jpg):
        return "Pillow is missing and this is not a PNG/JPEG file. Install it:  pkg install python-pillow"
    if not keep_bg:
        for _o in ("bg.jpg", "bg.png"):
            if os.path.exists(d + "/" + _o):
                os.remove(d + "/" + _o)
        _wr(d + ("/bg.jpg" if is_jpg else "/bg.png"), raw)
    for name in ("icon-192.png", "icon-512.png", "icon-maskable.png"):
        _wr(d + "/" + name, raw)
    _wr(d + "/header.txt", (("data:image/%s;base64," % ("jpeg" if is_jpg else "png")) + base64.b64encode(raw).decode()).encode()
        if len(raw) < 600000 else b"")
    return ""


def logo_cmd(path):
    """liquid --logo pic.png   makes the 3 app icons Chrome uses (Install app, home screen) + the page header logo."""
    d = APP + "/logo"
    if path == "reset":
        reset_logo()
        say("Picture removed everywhere. Reload the page.", "G")
        return 0
    if not os.path.isfile(path):
        say("Usage:  liquid --logo /storage/emulated/0/Download/mylogo.png", "O")
        return 1
    err = _make_icons(path)
    if err:
        say(err, "R")
        return 1
    open(d + "/custom", "w").write(str(time.time()))                            # written LAST: its time is the new picture version
    try:
        os.remove(d + "/nopic")
    except OSError:
        pass
    for fn in (auto_silhouette, refresh_copies, lambda: restyle_reports(True), _signal_note_refresh):
        try:
            fn()
        except Exception as e:
            log("logo step failed: %r" % (e,))
    ev("M", "\u25c6 logo changed from " + os.path.basename(path))
    say("Logo set everywhere (app icon, page, notifications, opening page, reports). Reload the page. "
        "A home-screen app made earlier keeps its old icon until Chrome updates it: remove it and tap Install app again.", "G")
    return 0


def setup():
    def step(n, t):
        say("[%d/7] %s" % (n, t), "G")

    def sh(c):
        return subprocess.run(c, shell=True).returncode
    step(1, "Storage access")
    if not os.path.isdir(DL) or not os.access(DL, os.R_OK):
        sh("termux-setup-storage")
        say("     Tap ALLOW on the pop-up...", "O")
        for _ in range(40):
            if os.path.isdir("/storage/emulated/0/Download") and os.access("/storage/emulated/0/Download", os.R_OK):
                break
            time.sleep(1)
    dl = "/storage/emulated/0/Download"
    if not os.access(dl, os.R_OK):
        say("FAILED: no storage access. Android Settings > Apps > Termux > Permissions > Files and media > Allow, "
            "then run this again.", "R")
        return 1
    globals()["DL"] = dl
    step(2, "Termux:API tools")
    if not shutil.which("termux-notification"):
        sh("pkg install -y termux-api")
    step(3, "Libraries for the tools")
    if sh('python -c "import mutagen, pyzipper, Cryptodome, PIL" >/dev/null 2>&1'):
        sh("pkg install -y python-pillow >/dev/null 2>&1")
        sh("pip install mutagen pyzipper pycryptodomex")
    step(4, "The  liquid  command, the page, auto start")
    os.makedirs(APP, exist_ok=True)
    dst = HOME + "/liquid_all.py"
    if os.path.abspath(SELF) != dst:
        shutil.copy2(SELF, dst)
        globals()["SELF"] = dst
    os.makedirs(PREFIX + "/bin", exist_ok=True)
    open(PREFIX + "/bin/liquid", "w").write('#!/bin/sh\nexec python "$HOME/liquid_all.py" "$@"\n')
    os.chmod(PREFIX + "/bin/liquid", 0o755)
    sh("sed -i '/liquid-server/d' ~/.bashrc 2>/dev/null; pkill -f '[l]iquid_run.sh'; pkill -f '[l]iquid_server.py'; "
       "pkill -f 'http[.]server 8080'; true")
    os.makedirs(HOME + "/bin", exist_ok=True)               # "Open with Termux" from the Files app runs this
    fe = HOME + "/bin/termux-file-editor"
    open(fe, "w").write('#!/data/data/com.termux/files/usr/bin/sh\ncase "$1" in *.py) exec python "$1" ;; *) exec ${EDITOR:-nano} "$1" ;; esac\n')
    os.chmod(fe, 0o755)
    sh("sed -i '/# liquid-guide/d' ~/.bashrc 2>/dev/null; echo 'python ~/liquid_all.py --guide 2>/dev/null # liquid-guide' >> ~/.bashrc")
    os.makedirs(HOME + "/.termux/boot", exist_ok=True)
    bf = HOME + "/.termux/boot/liquid-server.sh"
    open(bf, "w").write('#!/data/data/com.termux/files/usr/bin/sh\ntermux-wake-lock\n'
                        'nohup python "$HOME/liquid_all.py" --serve >/dev/null 2>&1 &\n')
    os.chmod(bf, 0o755)
    try:
        open(dl + "/liquid_commands.html", "w", encoding="utf-8").write(skin(text("liquid_start.html")))
    except OSError as e:
        say("     could not copy the page to Downloads: %s" % e, "O")
    step(5, "Start the server (stays on in the background)")
    if not ensure_server():
        say("FAILED: server not running. Read ~/liquid/server.log", "R")
        return 1
    step(6, "Open the page in Chrome")
    if not open_chrome():
        say("     Open Chrome and go to " + URL, "O")
    info()
    step(7, "Server options (also in the Setup tab of the page and in the  liquid  panel)")
    server_help()
    say("DONE. Type  liquid  in Termux any time: Chrome is the screen, Termux does the work.", "G")
    say("Keep it always on: install Termux:Boot (open it once) and set battery to Unrestricted for Termux.", "O")
    if sys.stdout.isatty() and "--no-follow" not in sys.argv:        # show the server's live activity here too, not only in Chrome
        print()
        say("LIVE FEED: everything the server does shows here (same as Chrome's Live activity). q = leave, the server keeps running.", "C")
        panel()
        follow()
    return 0


class _Pin:
    """17 Termux-only values (incl. kernel version) pinned to the bottom of the Termux window (not logged, not in the browser): clock, server PID,
    process state, open files, CPU time, disk read/write, context switches, activity.log size + lines, events seen, seconds
    since the last event, net total, net in/out, server memory, phone memory, phone uptime, usage, kernel. (The echo-cap note is the single LD feed line.)"""
    NR = 9                                   # 9 rows x 2 columns = 18 slots (17 values + kernel)
    H = NR + 2                               # + top and bottom border (shrinks by itself on a short screen, see reserve())
    lt = 0
    hold = False                             # SPACE pressed: only the feed lines are paused, the box keeps showing the live server
    lq = 0                                   # time of the last printed feed line
    # The box lives IN the normal flow of the terminal (no scroll region). Termux only keeps lines in its scrollback
    # when the whole screen scrolls, so every feed line that moves up stays there and you can scroll up at any time.

    def __init__(s):
        s.on = sys.stdout.isatty()
        s.t0, s.ev, s.last, s.rows, s.cols, s.c, s.up = time.time(), 0, 0, 0, 0, {}, False
        s._snap, s._bg_on = {}, False

    def _bg(s):
        """Collects the box numbers (phone info, server status, network) in the background. Reading them can take seconds
        (battery query, server check); doing that inside draw() used to freeze the feed, so a new action's line
        could appear late. draw() now only reads this cache and never waits."""
        while True:
            for k, fn in (("sys", s._sys), ("st", get_status), ("net", s._net)):
                try:
                    v = fn()
                    if k == "st" and v is None and s._snap.get("st"):
                        try:                                  # no answer: dead, or just busy? something still listening = busy
                            socket.create_connection(("127.0.0.1", PORT), .5).close()
                            continue                          # busy: keep the last good status (never show "offline" for a slow answer)
                        except OSError:
                            pass
                    s._snap[k] = v
                except Exception:
                    pass
            time.sleep(1)

    def _start_bg(s):
        if not s._bg_on:
            s._bg_on = True
            threading.Thread(target=s._bg, daemon=True).start()
            t = time.time()
            while not s._snap.get("sys") and time.time() - t < .4:   # first draw: give the sampler a moment, never longer
                time.sleep(.02)

    def _c(s, k, ttl, fn):
        t, v = s.c.get(k, (0, "?"))
        if time.time() - t > ttl:
            try:
                v = fn()
            except Exception:
                v = "?"
            s.c[k] = (time.time(), v)
        return v

    def _ip(s):
        x = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            x.connect(("10.255.255.255", 1))
            return x.getsockname()[0]
        finally:
            x.close()

    def _mem(s):
        st = get_status()
        for ln in open("/proc/%d/status" % st["pid"]):
            if ln.startswith("VmRSS"):
                return "%d MB" % (int(ln.split()[1]) // 1024)
        return "?"

    def _sys(s):
        return sysinfo()

    def _net(s):
        return net_bytes()

    def _thr(s):
        for ln in open("/proc/%d/status" % get_status()["pid"]):
            if ln.startswith("Threads"):
                return ln.split()[1]
        return "?"

    def _ping(s):
        t = time.time()
        socket.create_connection(("127.0.0.1", P.urlparse(URL).port or 8080), .5).close()
        return "%.1f ms" % ((time.time() - t) * 1000)

    def _dir(s):
        n = 0
        for r, _d, fs in os.walk(APP):
            for f in fs:
                try:
                    n += os.path.getsize(os.path.join(r, f))
                except OSError:
                    pass
        return n / 1048576.0

    def reserve(s):
        """Make room for the box under the cursor (the screen scrolls up by itself if needed), then step back to its top."""
        if not s.on or s.up:
            return
        s._start_bg()
        sz = shutil.get_terminal_size((45, 24))
        s.rows, s.cols = sz.lines, sz.columns
        s.nr = max(2, min(s.NR, sz.lines - 8))               # value rows that fit (keeps 6+ rows for the feed); 9 rows = all 18
        s.H = s.nr + 2
        sys.stdout.write("\n" * (s.H - 1) + "\x1b[%dA" % (s.H - 1))
        sys.stdout.flush()
        s.up, s.lt = True, 0

    def clear(s):
        """Take the box off the screen; the cursor is left where the box began, ready for normal printing."""
        if s.on and s.up:
            sys.stdout.write("\r\x1b[J")
            sys.stdout.flush()
        s.up = False

    def emit(s, items):
        """Print feed lines [(text, kind), ...] above the box. They scroll up into Termux's scrollback, so nothing is lost."""
        if not items:
            return
        s.clear()
        s.lq = time.time()
        gap = min(FEED_GAP, FEED_BURST / len(items))          # lines are shown one after the other, FEED_GAP apart (big bursts speed up)
        fd = sys.stdin.fileno() if sys.stdin and sys.stdin.isatty() else None
        for i, (t, k) in enumerate(items):
            say(t, k)
            try:
                sys.stdout.flush()
            except Exception:
                pass
            if gap > 0 and i < len(items) - 1:
                try:
                    if fd is not None and select.select([fd], [], [], gap)[0]:
                        gap = 0                               # a key was pressed: show the rest now, the key is handled next
                    elif fd is None:
                        time.sleep(gap)
                except Exception:
                    time.sleep(gap)
        s.lq = time.time()
        s.quiet = s.lq + PIN_QUIET                            # the action's lines are done: the box stays away for a while, then comes back

    def draw(s, force=False):
        if not s.on or not s.up or (not force and time.time() - s.lt < PIN_EVERY):   # values refresh every 3 s
            return
        if not force and time.time() < getattr(s, "quiet", 0):   # quiet time after an activity: no box yet
            return
        if not force and time.time() - s.lq < 1.5:            # an action is still printing lines: no box update in between
            return
        if not force and not s.hold:
            try:
                if os.path.getsize(APP + "/activity.log") > getattr(s, "pos", 1 << 60):   # an event is waiting: print it first
                    return
            except OSError:
                pass
        sz = shutil.get_terminal_size((45, 24))
        if (sz.lines, sz.columns) != (s.rows, s.cols):       # rotated phone / keyboard opened: make room again at the new size
            s.clear()
            s.reserve()
        s.lt = time.time()
        w, rows = max(20, sz.columns), sz.lines          # whole width (wrapping is off inside the box)
        R, D, K, V = "\x1b[0m", "\x1b[2m", "\x1b[96m", "\x1b[97m"

        def bar(p, inv=False, n=8):
            if p is None:
                return D + "\u2591" * n + R
            p = max(0, min(100, p))
            f = int(round(n * p / 100.0))
            bad = (100 - p) if inv else p
            c = 32 if bad < 60 else 33 if bad < 85 else 31
            return "\x1b[%dm%s%s%s%s" % (c, "\u2588" * f, D, "\u2591" * (n - f), R)

        def pc(x):
            return ("%3d%%" % x) if x is not None else "  ?%"
        d = s._snap.get("sys") or {}
        if not isinstance(d, dict):
            d = {}
        b = d.get("battery") or {}
        st = s._snap.get("st")
        cur = (st or {}).get("cur")
        run = bool(cur and cur.get("running"))
        rt, rf = d.get("ram_total"), d.get("ram_free")
        dt, df = d.get("disk_total"), d.get("disk_free")
        ru = int(round(100.0 * (1 - rf / float(rt)))) if rt and rf is not None else None
        du = int(round(100.0 * (1 - df / float(dt)))) if dt and df is not None else None
        bp = b.get("pct") if b.get("pct", -1) is not None and b.get("pct", -1) >= 0 else None
        try:
            nr, nt = s._snap["net"]
            o = getattr(s, "_n0", None)
            s._n0 = (time.time(), nr, nt)
            if o and s._n0[0] > o[0]:
                dd = s._n0[0] - o[0]
                s._nv = "\u2193%.0fK \u2191%.0fK/s" % ((nr - o[1]) / dd / 1024, (nt - o[2]) / dd / 1024)
        except Exception:
            s._nv = getattr(s, "_nv", "?")
        ld = d.get("load") or ["?"]
        age = ("%ds ago" % (time.time() - s.last)) if s.last else "none"
        el = int(time.time() - s.t0)
        tm = time.strftime("%I:%M:%S") + (".%02d" % (int(time.time() * 100) % 100)) + time.strftime(" %p")
        L = []
        pid = (st or {}).get("pid")

        def _x(fn):
            try:
                return fn()
            except Exception:
                return "?"

        def _rd(f):
            return open(f).read()
        lg = lambda f: _x(lambda: "%.0fK" % (os.path.getsize(APP + "/" + f) / 1024.0))
        sw = (100 - int(100.0 * d["swap_free"] / d["swap_total"])) if d.get("swap_total") else None
        ct = lambda k: _x(lambda: sum(int(l.split()[1]) for l in _rd("/proc/%d/status" % pid).splitlines() if k in l))
        mi = lambda k: _x(lambda: "%d MB" % (int([l for l in _rd("/proc/meminfo").splitlines() if l.startswith(k)][0].split()[1]) // 1024))
        def _iob():                                  # read/written by the server + every tool it ran (finished ones via rusage, the running one via /proc)
            r = w = 0
            for p_ in (pid, getattr(getattr(CUR, "p", None), "pid", 0) if CUR and CUR.code is None else 0):
                if p_:
                    try:
                        for l in _rd("/proc/%d/io" % p_).splitlines():
                            if l.startswith("read_bytes"):
                                r += int(l.split()[1])
                            elif l.startswith("write_bytes"):
                                w += int(l.split()[1])
                    except Exception:
                        pass
            try:
                import resource as _rs
                u = _rs.getrusage(_rs.RUSAGE_CHILDREN)
                r += u.ru_inblock * 512
                w += u.ru_oublock * 512
            except Exception:
                pass
            f = lambda b: "%dM" % (b // 1048576) if b >= 1048576 else "%dK" % (b // 1024)
            return "%s/%s" % (f(r), f(w))
        io = _x(_iob)
        cput = _x(lambda: "%.0fs" % (sum(int(v) for v in _rd("/proc/%d/stat" % pid).rsplit(")", 1)[1].split()[11:13]) / float(os.sysconf("SC_CLK_TCK"))))
        vl = lambda t: len(re.sub(r"\x1b\[[0-9;]*m", "", t))

        def cell(k, v, n, col=V):
            plain = re.sub(r"\x1b\[[0-9;]*m", "", str(v))
            t = " %s%-7s%s%s%s%s" % (D, k, R, col, plain, R)
            if vl(t) > n:
                t = (" %-7s%s" % (k, plain))[:n]
            return t + " " * max(0, n - vl(t))
        stt = _x(lambda: _rd("/proc/%d/stat" % pid).rsplit(")", 1)[1].split()[0])
        SN = {"S": "running", "R": "running", "D": "disk wait", "Z": "zombie", "T": "frozen"}   # S = idle between requests, still running; T = Android froze it (not stopped by you): it continues by itself
        lgk = _x(lambda: os.path.getsize(APP + "/activity.log") / 1024.0)
        G_, Y_, R_ = "\x1b[92m", "\x1b[93m", "\x1b[91m"
        # Termux-only values (nothing here repeats the shared live-activity tiles: CPU, RAM, battery, network ...)
        cm = lambda t: str(t).replace(" KB", "K").replace(" MB", "M").replace(" GB", "G")
        nj = s._c("nj", 2, lambda: (lambda j: j if j.get("pid") == pid else {})(json.load(open(APP + "/termux_net.json"))))   # only the running server's own numbers
        mm = (nj.get("mem") or {}) if isinstance(nj, dict) else {}
        us = s._c("us", 5, usage_stats)
        pu = s._c("pu", 5, uptime_secs)
        I = [("CLOCK", time.strftime("%I:%M:%S %p").lstrip("0"), V),
             ("PID", pid or "?", K), ("STATE",) + (("offline", R_) if ("st" in s._snap and not st) else ("checking", Y_) if not st else (SN.get(stt, stt), G_ if stt in ("S", "R") else (R_ if stt == "Z" else Y_))),
             ("FILES", _x(lambda: len(os.listdir("/proc/%d/fd" % pid))), K), ("CPU-T", cput, V),
             ("DISK", io, V), ("CTX", ct("ctxt_switches"), V),
             ("LOG", lg("activity.log"), (R_ if lgk != "?" and lgk > 900 else Y_ if lgk != "?" and lgk > 600 else G_)),
             ("LINES", _x(lambda: _rd(APP + "/activity.log").count("\n")), V),
             ("EVENTS", "%d" % s.ev, V), ("LAST", ("%ds" % (time.time() - s.last)) if s.last else "-", V),
             ("NET", _x(lambda: cm(_mbs(nj["rx"] + nj["tx"]))), V),
             ("IN/OUT", _x(lambda: "\u2193%s \u2191%s" % (cm(_mbs(nj["rx"])), cm(_mbs(nj["tx"])))), V),
             ("SRVMEM", _x(lambda: "%dM pk %dM" % (mm["rss"] // 1048576, mm["peak"] // 1048576)), V),
             ("PHONE", _x(lambda: "%+dM %s" % ((mm["used"] - mm["used0"]) // 1048576, cm(_gb(mm["used"])))), V),
             ("P-UP", _x(lambda: dur(pu) if pu else "?"), V),
             ("USAGE", _x(lambda: ("%dr %d%%ok" % (us["n"], us["pct"])) if us else "no runs"), V)]
        I.append(("KERNEL", _x(lambda: os.uname().release.split("-")[0]), V))   # Termux-only: phone kernel version, fills the 18th slot
        I = I[:2 * s.nr]
        cw = max(12, (w - 3) // 2)
        bd = lambda ch: D + ch + R

        def edge(l, r, left, right, fill="\u2500"):
            """top / bottom border with a label at each end, fitted to the width (labels drop out on a very narrow screen)"""
            room = w - 4
            if vl(left) + vl(right) + 1 > room:
                right = ""
            if vl(left) + vl(right) + 1 > room:
                left = ""
            gap = max(1, room - vl(left) - vl(right))
            return bd(l + "\u2500") + left + bd(fill * gap) + right + bd("\u2500" + r)
        hint = (" \x1b[1;93mFEED PAUSED" + R + D + " \u00b7 server keeps running \u00b7 SPACE " + R + "resume " + D + "\u00b7 q " + R + "leave ") if s.hold else \
            (" " + D + "SPACE " + R + "pause " + D + "\u00b7 q " + R + "leave ")
        stat = ""                                            # events seen + seconds since the last one are now value cells
        L = [edge("\u256d", "\u256e", " \x1b[1;95m\u25c9 TERMUX ONLY" + R + D + " \u00b7 server" + R + " ", "")]
        for i in range(0, len(I), 2):
            L.append(bd("\u2502") + cell(*I[i][:2], cw, I[i][2]) + bd("\u2502") + cell(*I[i + 1][:2], w - cw - 3, I[i + 1][2]) + bd("\u2502"))
        L.append(edge("\u2570", "\u256f", hint, stat))
        out = "\x1b[?7l"                                     # no wrapping inside the box
        for k, t in enumerate(L):
            out += "\r\x1b[2K%s\x1b[0m" % t + ("\x1b[1B" if k < len(L) - 1 else "")
        sys.stdout.write(out + "\x1b[?7h\r" + ("\x1b[%dA" % (len(L) - 1) if len(L) > 1 else ""))   # back to the box top (scroll-safe)
        sys.stdout.flush()

    def off(s):
        s.clear()


def follow():
    """Termux window: live coloured feed of what the server does + one-key server options, until q (the server keeps running)."""
    lg = APP + "/activity.log"
    say("WHILE YOU WERE AWAY (last events):", "D")
    recent(8)
    say("Live feed (server + Chrome + Termux activity). Scroll up any time, nothing is lost. SPACE = pause new lines, SPACE again = resume.  q = leave", "D")
    try:
        pos = os.path.getsize(lg)
    except OSError:
        pos = 0
    fd = sys.stdin.fileno() if sys.stdin and sys.stdin.isatty() else None
    old = None
    pin = _Pin()
    PIN[0] = pin
    hold = False
    lastln = ["", 0, 0]
    try:
        if fd is not None:
            old = termios.tcgetattr(fd)
            tty.setcbreak(fd)
        pin.reserve()
        pin.draw(True)
        while True:
            try:
                n = os.path.getsize(lg) if not hold else pos
                pre = b""
                if n < pos:
                    try:
                        with open(lg + ".1", "rb") as f:          # the log rotated: finish the old file first
                            f.seek(pos)
                            pre = f.read()
                    except OSError:
                        pre = b""
                    pos = 0
                if n > pos or pre:
                    chunk = pre
                    with open(lg, "rb") as f:
                        f.seek(pos)
                        chunk += f.read()
                        pos = f.tell()
                    items = []
                    for ln in chunk.decode("utf-8", "replace").splitlines():
                        sig = ln.split("|", 2)[0] + ln.split("|", 2)[-1]
                        if sig == lastln[0] and time.time() - lastln[1] < 5:
                            continue                             # same action line again: shown once only
                        lastln[0], lastln[1] = sig, time.time()
                        if time.time() < lastln[2] and any(w in ln for w in ("Termux", "server up", "server stopped")):
                            continue                             # you pressed that key here: its reply is already printed above
                        k, _, r = ln.partition("|")
                        tm, _, tx = r.partition("|")
                        tx, _, sh = tx.partition("|")            # Termux = short form if there is one, always cut to one line
                        if _is_live(k, sh):
                            continue                             # tiles / heartbeat: Chrome card only, Termux prints on events only
                        isL = k[:1] == "L" and len(k) == 2                 # a line the tool printed (echo)
                        kk = k[1:] if isL else k
                        if isL:                                            # no time stamp: the whole width is for the tool's own lines (boxes fit)
                            pf, ct = ((tm + "  \u2506 ", " " * (len(tm) + 2) + "\u2506 ") if ECHO_TIME else ("\u2506 ", "\u2506 "))
                        else:
                            pf, ct = tm + "  ", None
                        tx = pfit(pf, sh or tx, ct)                        # long lines wrap onto the next row, nothing is cut off
                        pin.ev, pin.last = pin.ev + 1, time.time()
                        items.append((tx, kk if kk in CLR else "W"))
                    pin.emit(items)
            except OSError:
                pass
            pin.pos = pos
            if True:
                if not pin.up and time.time() >= getattr(pin, "quiet", 0):
                    pin.reserve()                            # a normal print took the box off: bring it back under the lines
                pin.draw()                                   # after the events: a new action is always printed first, the box follows (every 3 s)
            if fd is None:
                time.sleep(.5)
            elif select.select([fd], [], [], .1)[0]:
                raw = os.read(fd, 1)
                if not raw:                                  # stdin closed: leave instead of spinning
                    break
                ch = raw.decode("utf-8", "ignore")
                if not ch:                                   # first byte of a non-ASCII key: nothing to do yet
                    continue
                if ch == " ":                                # pause: no new lines, box removed (scrolling up works without pausing too)
                    hold = not hold
                    pin.hold = hold
                    pin.clear()
                    if hold:
                        say("FEED PAUSED (only the printing, the server keeps running). New events are kept; SPACE again = resume.", "O")
                    pin.reserve()
                    pin.draw(True)
                    continue
                pin.clear()                                  # key output (info, log, ...) prints normally, then the box comes back
                if ch in "rksaApPtTn":
                    lastln[2] = time.time() + 12
                if hotkey(ch):
                    break
                if KEY_HOLD > 0 and ch not in ("h",):
                    try:
                        sys.stdout.flush()
                        select.select([fd], [], [], KEY_HOLD)   # stay still so the answer can be read (any key ends the wait)
                    except Exception:
                        pass
                pin.reserve()
                pin.draw(True)
    except KeyboardInterrupt:
        pin.clear()
        print()
    finally:
        pin.off()
        PIN[0] = None
        if old is not None:
            termios.tcsetattr(fd, termios.TCSADRAIN, old)


_WIPE2 = [0]
_WIPE3 = [0]


def hotkey(ch):
    """One key pressed in the live Termux panel. True = leave."""
    if not ch:
        return False
    c = cfg()
    if ch in ("q", "\x03", "\x04"):
        say("Left the panel. The server keeps running (liquid --stop to stop it).", "D")
        return True
    if ch == "x":
        stop_server()
        return True
    if ch == "o":
        say("Opening Chrome..." if open_chrome() else "Could not open Chrome. Open it and go to " + URL, "G")
    elif ch == "r":
        restart_server()
    elif ch == "k":
        kill_server()
    elif ch == "s":
        st = start_server()
        if st:
            started_msg(st)
    elif ch == "i":
        info()
    elif ch == "l":
        log_tail()
    elif ch == "d":
        print()
        dash()
    elif ch == "e":
        recent(25)
    elif ch in ("h", "?"):
        print()
        panel()
    elif ch == "c":
        cfg_line()
    elif ch in "aApPtT":
        k = {"a": "speed", "p": "pace", "t": "slow"}[ch.lower()]
        step = {"speed": .1, "pace": .05, "slow": .5}[k] * (1 if ch.isupper() else -1)
        new = cfg_set(**{k: c[k] + step})
        if new[k] != c[k]:
            ev("O", "\u2699 setting changed in Termux: %s %s>%s" % (k, c[k], new[k]))
        cfg_line(new)
    elif ch == "z":
        if time.time() - _WIPE2[0] < 6:
            _WIPE2[0] = 0
            if reset_start():
                say("Full reset in %d s: watch the feed and the notification. The server restarts by itself." % RESET_DELAY, "R")
        else:
            _WIPE2[0] = time.time()
            say("Press z again within 6 s to ERASE settings, logo, past runs, log, notifications and saved reports (learned model data is kept).", "O")
    elif ch == "m":
        model_cmd()
    elif ch == "M":
        if time.time() - _WIPE3[0] < 6:
            _WIPE3[0] = 0
            if model_reset("Termux"):
                say("Model learning data erased. Every model starts again from scratch.", "G")
        else:
            _WIPE3[0] = time.time()
            say("Press M again within 6 s to ERASE what every tool's model has learned (Reset Model's Learning Data).", "O")
    elif ch == "n":
        new = cfg_set(notify=0 if c["notify"] else 1)
        ev("O", "\u2699 notifications %s (set in Termux)" % ("on" if new["notify"] else "off"))
        cfg_line(new)
    return False


def main():
    a = sys.argv[1:]
    if "--hook" in a:
        return hook()
    if "--guide" in a:
        return quickstart()
    if "--help" in a or "-h" in a:
        banner()
        server_help()
        print()
        keys_help()
        return 0
    if "--watch" in a:
        ensure_server()
        return follow()
    if a[:1] == ["--tool"]:
        return run_tool(a[1], a[2:])
    if "--serve" in a:
        return serve()
    if "--respawn" in a:
        return respawn()
    if "--stop" in a:
        return stop_server()
    if "--kill" in a:
        return kill_server()
    if "--restart" in a:
        return 0 if restart_server() else 1
    if "--start" in a:
        st = start_server()
        if st:
            started_msg(st)
            if st and "--no-follow" not in a and sys.stdout.isatty():
                follow()
        return 0 if st else 1
    if "--status" in a or "--info" in a:
        return info()
    if "--dash" in a:
        dash()
        return 0
    if "--log" in a:
        return log_tail(25)
    if "--reset-run" in a:
        reset_run()
        return 0
    if "--reset-all" in a:
        return reset_cmd(a)
    if "--reset-model" in a:
        return model_reset_cmd(a)
    if "--model" in a:
        return model_cmd(a)
    if "--config" in a:
        return config_cmd(a[a.index("--config") + 1:])
    if "--logo" in a:
        i = a.index("--logo")
        return logo_cmd(a[i + 1] if i + 1 < len(a) else "")
    if "--silhouette" in a:
        i = a.index("--silhouette")
        return silhouette_cmd(a[i + 1] if i + 1 < len(a) and not a[i + 1].startswith("--") else "")
    if "--setup" in a:
        return setup()
    if a and not a[0].startswith("--"):
        name = resolve(a[0])
        if name:
            return run_tool(name, a[1:])
        say("Unknown tool '%s'. Tools: %s" % (a[0], "  ".join(TOOLS)), "R")
        return 1
    if "--no-follow" not in a and not a:
        hook(True)
        quickstart(True)
    st = start_server()
    if not st:
        return 1
    started_msg(st)
    if "--no-open" not in a and not open_chrome():
        say("Could not open Chrome. Open it and go to " + URL, "O")
    panel()
    if "--no-follow" not in a:
        follow()


if __name__ == "__main__":
    sys.exit(main())

