#|def _lgx_pearson(x, y):
#|    n = len(x)
#|    mx, my = sum(x) / n, sum(y) / n
#|    sx = sum((a - mx) ** 2 for a in x) ** .5
#|    sy = sum((b - my) ** 2 for b in y) ** .5
#|    return 0.0 if sx <= 0 or sy <= 0 else sum((a - mx) * (b - my) for a, b in zip(x, y)) / (sx * sy)
#|
#|
#|def _lgx_blr(xs, ys, xn):
#|    """Bayesian linear regression secs = a + b * size (ridge prior, newer runs weigh more). Returns (mean secs, sd secs)."""
#|    n = len(xs)
#|    w = [0.9 ** (n - 1 - i) for i in range(n)]
#|    sw = sum(w)
#|    mx = sum(a * b for a, b in zip(w, xs)) / sw
#|    sd = max(1e-9, (sum(a * (b - mx) ** 2 for a, b in zip(w, xs)) / sw) ** .5)
#|    z = [(a - mx) / sd for a in xs]
#|    lam = 0.05
#|    s11, s1z, szz = sw + lam * .01, sum(a * b for a, b in zip(w, z)), sum(a * b * b for a, b in zip(w, z)) + lam
#|    t1, tz = sum(a * b for a, b in zip(w, ys)), sum(a * b * c for a, b, c in zip(w, z, ys))
#|    det = s11 * szz - s1z * s1z
#|    a0, b0 = (szz * t1 - s1z * tz) / det, (s11 * tz - s1z * t1) / det
#|    res = [y - (a0 + b0 * q) for y, q in zip(ys, z)]
#|    sig2 = max(sum(a * r * r for a, r in zip(w, res)) / max(1.0, sw - 2), (0.03 * sum(ys) / n) ** 2)
#|    zn = (xn - mx) / sd
#|    q = (szz - 2 * s1z * zn + s11 * zn * zn) / det
#|    return a0 + b0 * zn, (sig2 * (1 + q)) ** .5
#|
